import { and, count, desc, eq } from "drizzle-orm"
import { NextResponse } from "next/server"
import { z } from "zod"

import { db } from "@/lib/db"
import { indexBranchStates, indexRuns } from "@/lib/db/schema"
import { getUserIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"

const querySchema = z.object({
  branch: z.string().trim().min(1).optional(),
  configHash: z.string().trim().min(1).optional(),
  status: z
    .enum(["planned", "ingesting", "indexing", "ready", "failed", "superseded"])
    .optional(),
  page: z.coerce.number().int().positive().max(10_000).default(1),
  limit: z.coerce.number().int().positive().max(100).default(20),
})

export async function GET(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const [userId, { integrationId }] = await Promise.all([
    getSessionUserId(),
    context.params,
  ])

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  const integration = await getUserIntegration(integrationId, userId)
  if (!integration) {
    return NextResponse.json({ error: "Integration not found." }, { status: 404 })
  }

  const url = new URL(request.url)
  const parsed = querySchema.safeParse({
    branch: url.searchParams.get("branch") ?? undefined,
    configHash: url.searchParams.get("configHash") ?? undefined,
    status: url.searchParams.get("status") ?? undefined,
    page: url.searchParams.get("page") ?? undefined,
    limit: url.searchParams.get("limit") ?? undefined,
  })

  return NextResponse.json({
    data: runs,
    pagination: {
      page,
      limit,
      total: totalCount,
      totalPages: Math.max(1, Math.ceil(totalCount / limit)),
    },
  })
}

import { headers } from "next/headers"
import { redirect } from "next/navigation"
import { ReactNode } from "react"

import { auth } from "@/lib/auth"

export default async function OnboardingLayout({ children }: { children: ReactNode }) {
  const session = await auth.api.getSession({
    headers: await headers(),
  })

  if (!session?.user?.id) {
    redirect("/")
  }

  return children
}

