import { eq } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'
import type { ArtifactStore, GitLabSource, IngestJob, VectorStore } from '@/lib/indexing/contracts'
import {
  finalizeIndexRun,
  markIndexRunFailed,
} from '@/lib/indexing/finalize'
import { runSnapshotIngest } from '@/lib/indexing/snapshot'
import { createFsArtifactStore } from '@/lib/indexing/stores/artifact-store.fs'
import { createPostgresVectorStore } from '@/lib/indexing/stores/vector-store.pg'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import type { IngestResult } from '@/lib/indexing/types'

type IngestProcessorDeps = {
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
}

const defaultDeps = (): IngestProcessorDeps => ({
  source: createGitLabSource(),
  vectorStore: createPostgresVectorStore(),
  artifactStore: createFsArtifactStore(),
})

const toErrorPayload = (error: unknown) => {
  if (error instanceof Error) {
    return {
      code: 'INGEST_FAILED',
      message: error.message.slice(0, 500),
      stack: error.stack?.slice(0, 1000) ?? null,
    }
  }

  return {
    code: 'INGEST_FAILED',
    message: 'Unexpected ingest failure.',
    stack: null,
  }
}

const cleanupStaleVectorsForRun = async (args: {
  runId: string
  branchStateId: string
  vectorStore: VectorStore
}) => {
  const stagedChanges = await db
    .select({
      path: indexRunFileChanges.path,
      changeType: indexRunFileChanges.changeType,
      fileId: indexRunFileChanges.fileId,
    })
    .from(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, args.runId))

  for (const change of stagedChanges) {
    await args.vectorStore.deleteStaleByPath({
      branchStateId: args.branchStateId,
      path: change.path,
      keepFileId: change.changeType === 'upsert' ? change.fileId : null,
    })
  }
}

export const processIngestJob = async (
  job: IngestJob,
  deps: IngestProcessorDeps = defaultDeps(),
): Promise<IngestResult> => {
  const [run] = await db
    .select({
      id: indexRuns.id,
      status: indexRuns.status,
      mode: indexRuns.mode,
      branchStateId: indexRuns.branchStateId,
      headSha: indexRuns.headSha,
      artifactsPrefix: indexRuns.artifactsPrefix,
      configHash: indexBranchStates.configHash,
      integrationId: indexBranchStates.integrationId,
    })
    .from(indexRuns)
    .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
    .where(eq(indexRuns.id, job.runId))
    .limit(1)

  if (!run) {
    return {
      runId: job.runId,
      status: 'skipped',
    }
  }

  if (run.status === 'ready' || run.status === 'superseded') {
    return {
      runId: run.id,
      status: 'skipped',
    }
  }

await db
  .update(indexRuns)
  .set({
    status: 'indexing',
    updatedAt: new Date(),
  })
  .where(eq(indexRuns.id, run.id))

try {
  if (run.mode === 'snapshot') {
    const snapshot = await runSnapshotIngest({
      run: {
        runId: run.id,
        branchStateId: run.branchStateId,
        integrationId: run.integrationId,
        configHash: run.configHash,
        headSha: run.headSha,
        artifactsPrefix: run.artifactsPrefix,
      },
      source: deps.source,
      vectorStore: deps.vectorStore,
      artifactStore: deps.artifactStore,
    })

    await db
      .update(indexRuns)
      .set({
        stats: snapshot.stats,
        updatedAt: new Date(),
      })
      .where(eq(indexRuns.id, run.id))
  } else {
    throw new Error('Delta ingest is not implemented yet (Phase 2).')
  }
} catch (error) {
  await markIndexRunFailed(run.id, toErrorPayload(error))

  return {
    runId: run.id,
    status: 'failed',
  }
}

const finalized = await finalizeIndexRun(run.id)
if (finalized.status === 'not_found' || finalized.status === 'invalid_state') {
  return {
    runId: run.id,
    status: 'skipped',
  }
}

  if (finalized.status === 'ready') {
    try {
      await cleanupStaleVectorsForRun({
        runId: run.id,
        branchStateId: run.branchStateId,
        vectorStore: deps.vectorStore,
      })
    } catch (error) {
      await db
        .update(indexRuns)
        .set({
          error: {
            code: 'VECTOR_GC_FAILED',
            message: error instanceof Error ? error.message.slice(0, 500) : 'Vector cleanup failed.',
          },
          updatedAt: new Date(),
        })
        .where(eq(indexRuns.id, run.id))
    }
  }

  return {
    runId: run.id,
    status: finalized.status,
  }
}

import {
  index,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";
import { user } from "./auth";

export const onboardingEventEnum = pgEnum("onboarding_event", [
  "onboarding_started",
  "onboarding_token_validated",
  "onboarding_projects_selected",
  "onboarding_completed",
]);

export type OnboardingEventMetadata = {
  instanceUrl?: string;
  selectedProjectCount?: number;
  projectId?: string;
  mergeRequestId?: string;
};

export const onboardingEvents = pgTable(
  "onboarding_events",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    event: onboardingEventEnum("event").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    metadata: jsonb("metadata").$type<OnboardingEventMetadata>(),
  },
  (table) => [
    index("onboarding_events_user_id_idx").on(table.userId),
    index("onboarding_events_event_idx").on(table.event),
    index("onboarding_events_created_at_idx").on(table.createdAt),
  ],
);

const getEnvAiDefaults = (): AISettings => ({
  apiUrl:
    process.env.NEXT_PUBLIC_AI_API_URL?.trim() ||
    process.env.NEXT_PUBLIC_OPENAI_BASE_URL?.trim() ||
    DEFAULT_AI_API_URL,
  model:
    process.env.NEXT_PUBLIC_AI_MODEL?.trim() ||
    process.env.NEXT_PUBLIC_OPENAI_MODEL?.trim() ||
    DEFAULT_AI_MODEL,
})

const defaultAiSettings = {
  ...getEnvAiDefaults(),
} satisfies AISettings

const THEME_MODES: Array<{ value: ThemeMode; label: string }> = [
  { value: "system", label: "System" },
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
  { value: "argus", label: "Argus" },
] as const

const SETTINGS_AUTOSAVE_DEBOUNCE_MS = 100

const isThemeMode = (value: string | null): value is ThemeMode =>
  value === "system" || value === "light" || value === "dark" || value === "argus"

const getActualThemeMode = (mode: ThemeMode) => {
  if (mode === "argus") {
    const prefersDark = typeof window !== "undefined" &&
      window.matchMedia("(prefers-color-scheme: dark)").matches
    return prefersDark ? "argus-dark" : "argus-light"
  }
  return mode
}

const statusLabel: Record<IntegrationStatus, string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const formatDateTime = (value: string | null) => {
  if (!value) {
    return "Never"
  }

  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "Unknown"
  }

  return parsed.toLocaleString()
}

const readTokenValue = (raw: string | null, key: "us" | "global" | "public"): string => {
  if (!raw) {
    return ""
  }

  try {
    const parsed = JSON.parse(raw) as Partial<SavedTokens>
    const value = parsed[key]
    return typeof value === "string" ? value : ""
  } catch {
    return ""
  }
}

const readSavedTokensFromStorage = (): SavedTokens => {
  if (typeof window === "undefined") {
    return emptyTokens
  }

  const gitlabRaw = window.localStorage.getItem(GITLAB_STORAGE_KEY)
  if (!gitlabRaw) {
    return emptyTokens
  }

  return {
    us: readTokenValue(gitlabRaw, "us"),
    global: readTokenValue(gitlabRaw, "global"),
    public: readTokenValue(gitlabRaw, "public"),
  }
}

const readAiSettingsFromStorage = (): AISettings => {
  const envDefaults = getEnvAiDefaults()
  if (typeof window === "undefined") {
    return envDefaults
  }

  const aiRaw = window.localStorage.getItem(AI_SETTINGS_STORAGE_KEY)
  if (!aiRaw) {
    return envDefaults
  }

  try {
    const parsed = JSON.parse(aiRaw) as Partial<AISettings>
    return {
      apiUrl:
        typeof parsed.apiUrl === "string" && parsed.apiUrl.trim().length > 0
          ? parsed.apiUrl
          : envDefaults.apiUrl,
      model:
        typeof parsed.model === "string" && parsed.model.trim().length > 0
          ? parsed.model
          : envDefaults.model,
    }
  } catch {
    return envDefaults
  }
}

const readThemeModeFromStorage = (): ThemeMode => {
  if (typeof window === "undefined") {
    return "system"
  }

  const themeRaw = window.localStorage.getItem(THEME_SETTINGS_STORAGE_KEY)
  return isThemeMode(themeRaw) ? themeRaw : "system"
}

export default function SettingsPage() {
  const [activeTab, setActiveTab] = useState("gitlab")
  const [integrations, setIntegrations] = useState<GitLabIntegration[]>([])
  const [integrationBusyId, setIntegrationBusyId] = useState<string | null>(null)
  const [integrationStatus, setIntegrationStatus] = useState("")
  const [tokens, setTokens] = useState<SavedTokens>(() => readSavedTokensFromStorage())
  const [gitlabStatus, setGitlabStatus] = useState("")
  const [aiSettings, setAiSettings] = useState<AISettings>(() => readAiSettingsFromStorage())
  const [aiStatus, setAiStatus] = useState("")
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => readThemeModeFromStorage())
  const [themeStatus, setThemeStatus] = useState("")
  const { setTheme } = useTheme()
  const gitlabAutoSaveTimer = useRef<number | null>(null)
  const aiAutoSaveTimer = useRef<number | null>(null)
  const themeAutoSaveTimer = useRef<number | null>(null)
  const hasInitializedGitlabAutoSave = useRef(false)
  const hasInitializedAiAutoSave = useRef(false)
  const hasInitializedThemeAutoSave = useRef(false)

  useEffect(() => {
    setTheme(getActualThemeMode(themeMode))
  }, [setTheme, themeMode])

  const handleTokenChange = (key: GitlabInstanceKey, value: string) => {
    setTokens((current) => ({
      ...current,
      [key]: value,
    }))
  }

const handleAiSettingChange = (
  key: keyof AISettings,
  value: string,
) => {
  setAiSettings((current) => ({
    ...current,
    [key]: value,
  }))
}

const clearStatusLater = (setStatus: (value: string) => void) => {
  window.setTimeout(() => {
    setStatus("")
  }, 2000)
}

const loadIntegrations = useCallback(async () => {
  const response = await fetch("/api/gitlab/integrations", {
    method: "GET",
    headers: {
      "content-type": "application/json",
    },
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    const message =
      payload &&
        typeof payload === "object" &&
        "error" in payload &&
        typeof (payload as { error?: unknown }).error === "string"
        ? (payload as { error: string }).error
        : "Failed to load integrations."
    throw new Error(message)
  }

  const data =
    payload &&
      typeof payload === "object" &&
      "data" in payload &&
      Array.isArray((payload as { data?: unknown }).data)
      ? (payload as { data: GitLabIntegration[] }).data
      : []

  setIntegrations(data)
}, [])

const callIntegrationAction = useCallback(async (
  integrationId: string,
  action: "resync" | "disconnect",
  token?: string,
) => {
  const response = await fetch(`/api/gitlab/integrations/${integrationId}/${action}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify(token ? { token } : {}),
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    const message =
      payload &&
        typeof payload === "object" &&
        "error" in payload &&
        typeof (payload as { error?: unknown }).error === "string"
        ? (payload as { error: string }).error
        : `Failed to ${action} integration.`
    throw new Error(message)
  }

  return payload
}, [])

const runIntegrationAction = useCallback(async (
  integrationId: string,
  action: "resync" | "disconnect",
  options?: { token?: string },
) => {
  setIntegrationBusyId(integrationId)
  try {
    const payload = await callIntegrationAction(integrationId, action, options?.token)
    const warning =
      payload &&
        typeof payload === "object" &&
        "warning" in payload &&
        typeof (payload as { warning?: unknown }).warning === "string"
        ? (payload as { warning: string }).warning
        : ""

    setIntegrationStatus(
      warning ||
      (action === "resync"
        ? "Integration resync requested."
        : "Integration disconnected."),
    )
    clearStatusLater(setIntegrationStatus)
    await loadIntegrations()
  } catch (error) {
    setIntegrationStatus(error instanceof Error ? error.message : "Action failed.")
    clearStatusLater(setIntegrationStatus)
  } finally {
    setIntegrationBusyId(null)
  }
}, [callIntegrationAction, loadIntegrations])

useEffect(() => {
  void loadIntegrations().catch((error) => {
    setIntegrationStatus(error instanceof Error ? error.message : "Failed to load integrations.")
  })
}, [loadIntegrations])

const clearTokens = () => {
  setTokens(emptyTokens)
  setGitlabStatus("GitLab tokens cleared.")
  clearStatusLater(setGitlabStatus)
}

const clearAISettings = () => {
  setAiSettings(defaultAiSettings)
  setAiStatus("AI settings cleared.")
  clearStatusLater(setAiStatus)
}

const handleResyncIntegration = (integrationId: string) => {
  void runIntegrationAction(integrationId, "resync")
}

const handleRotateToken = (integrationId: string) => {
  const token = window.prompt("Paste replacement GitLab personal access token")
  if (!token || !token.trim()) {
    return
  }
  void runIntegrationAction(integrationId, "resync", { token: token.trim() })
}

const handleDisconnectIntegration = (integrationId: string, projectPath: string) => {
  const confirmed = window.confirm(
    `Unlink ${projectPath} from your account? If this is the last membership, webhook access is disabled.`,
  )
  if (!confirmed) {
    return
  }
  void runIntegrationAction(integrationId, "disconnect")
}

const handleThemeModeChange = (value: ThemeMode) => {
  setThemeMode(value)
}

useEffect(() => {
  if (!hasInitializedGitlabAutoSave.current) {
    hasInitializedGitlabAutoSave.current = true
    return
  }
  if (gitlabAutoSaveTimer.current) {
    window.clearTimeout(gitlabAutoSaveTimer.current)
    gitlabAutoSaveTimer.current = null
  }
  gitlabAutoSaveTimer.current = window.setTimeout(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(GITLAB_STORAGE_KEY, JSON.stringify(tokens))
      setGitlabStatus("GitLab changes auto-saved.")
      clearStatusLater(setGitlabStatus)
    }
    gitlabAutoSaveTimer.current = null
  }, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  return () => {
    if (gitlabAutoSaveTimer.current) {
      window.clearTimeout(gitlabAutoSaveTimer.current)
      gitlabAutoSaveTimer.current = null
    }
  }
}, [tokens])

useEffect(() => {
  if (!hasInitializedAiAutoSave.current) {
    hasInitializedAiAutoSave.current = true
    return
  }
  if (aiAutoSaveTimer.current) {
    window.clearTimeout(aiAutoSaveTimer.current)
