      <p className="text-sm text-muted-foreground">
        Configure GitLab integrations, local tokens, AI settings, and theme.
      </p>
    </section>

    )}
    <p className="text-xs text-muted-foreground">
      {integrationStatus || "Server integration status is up to date."}
    </p>
