const ALLOWED_MERGE_REQUEST_ACTIONS = new Set(["open", "reopen", "update", "merge"])

type NormalizedWebhookEvent = {
  eventType: "push" | "merge_request" | "ignored"
  jobType?: "push" | "merge_request"
  ref: string | null
  normalizedPayload?: Record<string, unknown>
}

const asObject = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const asString = (value: unknown) =>
  typeof value === "string" && value.trim().length > 0 ? value : null

const asNumberString = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value)
  }
  if (typeof value === "string" && value.trim()) {
    return value.trim()
  }
  return null
}

export const classifyWebhookEvent = (
  eventName: string,
  payload: Record<string, unknown>,
): NormalizedWebhookEvent => {

  const ref = asString(payload.ref)

  if (eventName === "Push Hook") {
    if (!ref || !ref.startsWith("refs/heads/")) {
      return {
        eventType: "ignored",
        ref,
      }
    }

    const after = asString(payload.after)
    if (!after) {
      return {
        eventType: "ignored",
        ref,
      }
    }

    return {
      eventType: "push",
      jobType: "push",
      ref,
      normalizedPayload: {
        ref,
        before: asString(payload.before),
        after,
        checkoutSha: asString(payload.checkout_sha),
      },
    }
  }

  if (eventName === "Merge Request Hook") {
    const objectAttributes = asObject(payload.object_attributes)
    const action = asString(objectAttributes?.action)

    if (!action || !ALLOWED_MERGE_REQUEST_ACTIONS.has(action)) {
      return {
        eventType: "ignored",
        ref,
      }
    }

    const mergeRequestIid = asNumberString(objectAttributes?.iid)
    if (!mergeRequestIid) {
      return {
        eventType: "ignored",
        ref,
      }
    }

    const lastCommit = asObject(objectAttributes?.last_commit)

    return {
      eventType: "merge_request",
      jobType: "merge_request",
      ref,
      normalizedPayload: {
        mergeRequestIid,
        action,
        sourceBranch: asString(objectAttributes?.source_branch),
        targetBranch: asString(objectAttributes?.target_branch),
        state: asString(objectAttributes?.state),
        lastCommitSha: asString(lastCommit?.id),
      },
    }
  }

  return {
    eventType: "ignored",
    ref,
  }
}

export class FsArtifactStore implements ArtifactStore {
  private readonly root = resolveArtifactsRoot()
  private readonly resolvedRoot = path.resolve(this.root)

  private async ensureRunDir(prefix: string) {
    const runDir = path.resolve(this.resolvedRoot, prefix)
    const rootWithSeparator = `${this.resolvedRoot}${path.sep}`
    const isWithinRoot = runDir === this.resolvedRoot || runDir.startsWith(rootWithSeparator)
    if (!isWithinRoot) {
      throw new Error("Invalid artifacts prefix path.")
    }

    await mkdir(runDir, { recursive: true })
    return runDir
  }

  async writeRunJson(args: { artifactsPrefix: string; run: unknown }): Promise<void> {
    const runDir = await this.ensureRunDir(args.artifactsPrefix)
    await writeFile(path.join(runDir, 'run.json'), `${JSON.stringify(args.run, null, 2)}\n`, 'utf8')
  }

  async writeManifest(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
    const runDir = await this.ensureRunDir(args.artifactsPrefix)
    await writeLinesFile(path.join(runDir, 'manifest.jsonl'), args.lines)
  }

  async writeChangedFiles(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
    const runDir = await this.ensureRunDir(args.artifactsPrefix)
    await writeLinesFile(path.join(runDir, 'changed_files.jsonl'), args.lines)
  }
}

export const createFsArtifactStore = () => new FsArtifactStore()

