import { eq, lt, sql } from "drizzle-orm"

import { db } from "@/lib/db"
import { gitlabJobs, gitlabWebhookDeliveries } from "@/lib/db/schema"
import {
  getCommitDetails,
  getMergeRequestChanges,
  getMergeRequestDetails,
} from "@/lib/gitlab/client"
import {
  GITLAB_MAX_JOB_ATTEMPTS,
  GITLAB_WEBHOOK_RETENTION_DAYS,
} from "@/lib/gitlab/constants"
import { gitlabEnv } from "@/lib/gitlab/env"
import {
  decryptIntegrationToken,
  getIntegrationById,
  syncIntegrationWebhook,
} from "@/lib/gitlab/service"

type ClaimedJob = {
  id: string
  integrationId: string
  deliveryId: string | null
  jobType: "push" | "merge_request" | "hook_sync"
  attempts: number
  normalizedPayload: Record<string, unknown> | null
}

const parseNormalizedPayload = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const parseJobType = (value: unknown): ClaimedJob["jobType"] => {
  if (value === "push" || value === "merge_request" || value === "hook_sync") {
    return value
  }
  throw new Error("Invalid claimed job type.")
}

const claimDueJobs = async (batchSize: number): Promise<ClaimedJob[]> => {
  const query = sql<ClaimedJob>`
    with due_jobs as (
      select ${gitlabJobs.id}
      from ${gitlabJobs}
      where ${gitlabJobs.status} in ('pending', 'failed')
        and ${gitlabJobs.nextAttemptAt} <= now()
      order by ${gitlabJobs.nextAttemptAt} asc
      for update skip locked
      limit ${batchSize}
    )
    update ${gitlabJobs}
      set
        ${gitlabJobs.status} = 'processing',
        ${gitlabJobs.startedAt} = now(),
        ${gitlabJobs.updatedAt} = now(),
        ${gitlabJobs.attempts} = ${gitlabJobs.attempts} + 1
    from due_jobs
    where ${gitlabJobs.id} = due_jobs.id
    returning
      ${gitlabJobs.id} as "id",
      ${gitlabJobs.integrationId} as "integrationId",
      ${gitlabJobs.deliveryId} as "deliveryId",
      ${gitlabJobs.jobType} as "jobType",
      ${gitlabJobs.attempts} as "attempts",
      ${gitlabJobs.normalizedPayload} as "normalizedPayload"
  `

  const result = await db.execute(query)
  return result.rows.map((rawRow) => {
    const row = rawRow as Record<string, unknown>
    return {
      id: String(row.id),
      integrationId: String(row.integrationId),
      deliveryId: typeof row.deliveryId === "string" ? row.deliveryId : null,
      jobType: parseJobType(row.jobType),
      attempts: Number(row.attempts),
      normalizedPayload: parseNormalizedPayload(row.normalizedPayload),
    }
  })
}

const getRetryDelayMs = (attempt: number) => {
  const exponent = Math.max(0, attempt - 1)
  const baseDelayMs = 30_000
  return Math.min(60 * 60 * 1_000, baseDelayMs * 2 ** exponent)
}

const markJobSucceeded = async (jobId: string, result: Record<string, unknown>) => {
  await db
    .update(gitlabJobs)
    .set({
      status: "succeeded",
      finishedAt: new Date(),
      lastError: null,
      result,
      updatedAt: new Date(),
    })
    .where(eq(gitlabJobs.id, jobId))
}

const markJobFailed = async ({
  job,
  error,
}: {
  job: ClaimedJob
  error: unknown
}) => {
  const message =
    error instanceof Error ? error.message.slice(0, 500) : "Unexpected job processing error."

  const exceededAttempts = job.attempts >= GITLAB_MAX_JOB_ATTEMPTS
  await db
    .update(gitlabJobs)
    .set({
      status: exceededAttempts ? "dead" : "failed",
      finishedAt: exceededAttempts ? new Date() : null,
      nextAttemptAt: exceededAttempts
        ? new Date()
        : new Date(Date.now() + getRetryDelayMs(job.attempts)),
      lastError: message,
      updatedAt: new Date(),
    })
    .where(eq(gitlabJobs.id, job.id))

  return exceededAttempts
}

const readString = (
  payload: Record<string, unknown> | null,
  key: string,
  fieldName: string,
) => {
  const value = payload?.[key]
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`Missing ${fieldName} in job payload.`)
  }
  return value
}

const processPushJob = async (job: ClaimedJob) => {
  const integration = await getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for push job.")
  }

  const afterSha = readString(job.normalizedPayload, "after", "after")
  const token = decryptIntegrationToken(integration)
  const commit = await getCommitDetails(
    integration.instanceUrl,
    token,
    integration.projectId,
    afterSha,
  )

  return {
    type: "push",
    ref: typeof job.normalizedPayload?.ref === "string" ? job.normalizedPayload.ref : null,
    after: afterSha,
    commit,
  }
}

const processMergeRequestJob = async (job: ClaimedJob) => {
  const integration = await getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for merge request job.")
  }

  const mergeRequestIid = readString(
    job.normalizedPayload,
    "mergeRequestIid",
    "mergeRequestIid",
  )

  const token = decryptIntegrationToken(integration)
  const mergeRequest = await getMergeRequestDetails(
    integration.instanceUrl,
    token,
    integration.projectId,
    mergeRequestIid,
  )

  let changes: Record<string, unknown> | null = null
  try {
    changes = await getMergeRequestChanges(
      integration.instanceUrl,
      token,
      integration.projectId,
      mergeRequestIid,
    )
  } catch {
    changes = null
  }

  return {
    type: "merge_request",
    mergeRequestIid,
    mergeRequest,
    ...(changes ? { changes } : {}),
  }
}

const processHookSyncJob = async (job: ClaimedJob) => {
  const integration = await getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for hook sync job.")
  }

  const token = decryptIntegrationToken(integration)
  const syncResult = await syncIntegrationWebhook({
    integration,
    token,
  })

  if (!syncResult.ok) {
    throw new Error(syncResult.error ?? "Hook sync failed.")
  }

  return {
    type: "hook_sync",
    reason:
      typeof job.normalizedPayload?.reason === "string"
        ? job.normalizedPayload.reason
        : "scheduled",
  }
}

const processClaimedJob = async (job: ClaimedJob): Promise<Record<string, unknown>> => {
  if (job.jobType === "push") {
    return processPushJob(job)
  }

  if (job.jobType === "merge_request") {
    return processMergeRequestJob(job)
  }

  return processHookSyncJob(job)
}

export const runGitLabJobRunner = async (batchSize = gitlabEnv.jobBatchSize) => {
  const normalizedBatchSize = Math.min(200, Math.max(1, Math.floor(batchSize)))
  const jobs = await claimDueJobs(normalizedBatchSize)

  const summary = {
    claimed: jobs.length,
    succeeded: 0,
    failed: 0,
    dead: 0,
  }

  for (const job of jobs) {
    try {
      const result = await processClaimedJob(job)
      await markJobSucceeded(job.id, result)
      summary.succeeded += 1
    } catch (error) {
      const isDead = await markJobFailed({ job, error })
      if (isDead) {
        summary.dead += 1
      } else {
        summary.failed += 1
      }
    }
  }

  return summary
}

export const cleanupOldWebhookDeliveries = async (
  retentionDays = GITLAB_WEBHOOK_RETENTION_DAYS,
) => {
  const normalizedDays = Math.max(1, Math.floor(retentionDays))
  const cutoff = new Date(Date.now() - normalizedDays * 24 * 60 * 60 * 1_000)

  const deleted = await db
    .delete(gitlabWebhookDeliveries)
    .where(lt(gitlabWebhookDeliveries.receivedAt, cutoff))
    .returning({ id: gitlabWebhookDeliveries.id })

  return {
    deletedDeliveries: deleted.length,
    retentionDays: normalizedDays,
  }
}

import { OnboardingFlow } from "@/components/onboarding/onboarding-flow"

export default function OnboardingMergeRequestsPage() {
  return <OnboardingFlow routeStep="mrs" />
}

import { describe, expect, test } from "bun:test"

const loadNormalizer = async (allowPrivateHosts?: string) => {
  const previous = process.env.GITLAB_ALLOW_PRIVATE_HOSTS
  if (allowPrivateHosts === undefined) {
    delete process.env.GITLAB_ALLOW_PRIVATE_HOSTS
  } else {
    process.env.GITLAB_ALLOW_PRIVATE_HOSTS = allowPrivateHosts
  }

  try {
    const mod = await import(`./instance.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
    return mod.normalizeGitLabInstanceUrl as (input: string) => string
  } finally {
    if (previous === undefined) {
      delete process.env.GITLAB_ALLOW_PRIVATE_HOSTS
    } else {
      process.env.GITLAB_ALLOW_PRIVATE_HOSTS = previous
    }
  }
}

describe("normalizeGitLabInstanceUrl", () => {
  test("normalizes valid public URLs", async () => {
    const normalize = await loadNormalizer()

    expect(normalize("gitlab.com/")).toBe("https://gitlab.com")
    expect(normalize("https://gitlab.com/group/project/?foo=bar#frag")).toBe(
      "https://gitlab.com/group/project",
    )
  })

  test("rejects credentials and private hosts by default", async () => {
    const normalize = await loadNormalizer()

    expect(() => normalize("https://user:pass@gitlab.com")).toThrow(
      "GitLab instance URL must not include credentials.",
    )
    expect(() => normalize("http://localhost:3000")).toThrow(
      "GitLab instance URL must use a public host.",
    )
    expect(() => normalize("http://127.0.0.1:3000")).toThrow(
      "GitLab instance URL must use a public host.",
    )
    expect(() => normalize("http://192.168.1.10")).toThrow(
      "GitLab instance URL must use a public host.",
    )
  })

  test("allows private hosts when explicitly enabled", async () => {
    const normalize = await loadNormalizer("1")
    expect(normalize("http://localhost:3000")).toBe("http://localhost:3000")
  })
})

import { inArray, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import { indexEmbeddingCache } from '@/lib/db/schema'
import { INDEX_VECTOR_DIMENSION } from '@/lib/indexing/constants'
import type { VectorChunkRecord } from '@/lib/indexing/contracts'
import { sha256Hex } from '@/lib/utils/hash'

type EmbeddingProvider = 'openai' | 'deterministic'

const DEFAULT_EMBEDDING_MODEL = 'text-embedding-3-small'
const DEFAULT_OPENAI_BASE_URL = 'https://api.openai.com/v1'

const parsePositiveInt = (value: string | undefined, fallback: number): number => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

const normalizeEmbedding = (embedding: number[]): number[] => {
  if (embedding.length !== INDEX_VECTOR_DIMENSION) {
    throw new Error(
      `Embedding dimension mismatch. Expected ${INDEX_VECTOR_DIMENSION}, received ${embedding.length}.`,
    )
  }

  return embedding.map((value) => {
    if (!Number.isFinite(value)) {
      throw new Error('Embedding contains non-finite values.')
    }

    return Number(value.toFixed(8))
  })
}

const embedTextDeterministic = (text: string, dimension: number): number[] => {
  const values: number[] = []
  let counter = 0

  while (values.length < dimension) {
    const hash = sha256Hex(`${text}:${counter}`)
    for (let offset = 0; offset < hash.length && values.length < dimension; offset += 2) {
      const byte = Number.parseInt(hash.slice(offset, offset + 2), 16)
      const normalized = (byte / 255) * 2 - 1
      values.push(Number(normalized.toFixed(8)))
    }
    counter += 1
  }

  return values
}

const resolveProvider = (): EmbeddingProvider => {
  const configured = process.env.INDEXER_EMBEDDING_PROVIDER?.trim().toLowerCase()
  if (configured === 'deterministic') {
    return 'deterministic'
  }

  return 'openai'
}

const resolveEmbeddingModel = () =>
  process.env.INDEXER_EMBEDDING_MODEL?.trim() ||
  process.env.OPENAI_EMBEDDING_MODEL?.trim() ||
  DEFAULT_EMBEDDING_MODEL

const resolveBaseUrl = () =>
  (process.env.INDEXER_EMBEDDING_BASE_URL?.trim() ||
    process.env.OPENAI_BASE_URL?.trim() ||
    DEFAULT_OPENAI_BASE_URL
  ).replace(/\/+$/, '')

const resolveApiKey = () =>
  process.env.INDEXER_EMBEDDING_API_KEY?.trim() || process.env.OPENAI_API_KEY?.trim() || ''

const resolveCacheModelKey = () => {
  const provider = resolveProvider()
  if (provider === 'deterministic') {
    return 'deterministic:sha256-v1'
  }

  return `openai:${resolveBaseUrl()}:${resolveEmbeddingModel()}`
}

const parseOpenAiResponse = (payload: unknown): number[][] => {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid embedding response payload.')
  }

  const maybeData = (payload as { data?: unknown }).data
  if (!Array.isArray(maybeData)) {
    throw new Error('Embedding response missing data array.')
  }

  return maybeData.map((entry, index) => {
    const embedding = (entry as { embedding?: unknown })?.embedding
    if (!Array.isArray(embedding)) {
      throw new Error(`Embedding response item ${index} is missing embedding array.`)
    }

    return normalizeEmbedding(embedding as number[])
  })
}

const requestOpenAiEmbeddings = async (inputs: string[]): Promise<number[][]> => {
  const apiKey = resolveApiKey()
  if (!apiKey) {
    throw new Error(
      'Missing embedding API key. Set INDEXER_EMBEDDING_API_KEY (or OPENAI_API_KEY).',
    )
  }

  const model = resolveEmbeddingModel()
  const url = `${resolveBaseUrl()}/embeddings`
  const timeoutMs = parsePositiveInt(process.env.INDEXER_EMBEDDING_TIMEOUT_MS, 30_000)
  const maxAttempts = parsePositiveInt(process.env.INDEXER_EMBEDDING_RETRIES, 3)

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model,
        input: inputs,
      }),
      signal: AbortSignal.timeout(timeoutMs),
    })

    if (!response.ok) {
      const bodyText = (await response.text()).slice(0, 500)
      const isRetryable = response.status === 429 || response.status >= 500
      if (!isRetryable || attempt === maxAttempts) {
        throw new Error(
          `Embedding request failed (${response.status}): ${bodyText || response.statusText}`,
        )
      }

      await sleep(200 * 2 ** (attempt - 1))
      continue
    }

    const payload = await response.json()
    const embeddings = parseOpenAiResponse(payload)
    if (embeddings.length !== inputs.length) {
      throw new Error(
        `Embedding response count mismatch. Expected ${inputs.length}, received ${embeddings.length}.`,
      )
    }

    return embeddings
  } catch (error) {
    if (attempt === maxAttempts) {
      throw error
    }

    await sleep(200 * 2 ** (attempt - 1))
  }
}

throw new Error('Embedding request failed unexpectedly.')

}

const embedTexts = async (inputs: string[]): Promise<number[][]> => {
  if (inputs.length === 0) {
    return []
  }

  if (resolveProvider() === 'deterministic') {
    return inputs.map((input) => normalizeEmbedding(embedTextDeterministic(input, INDEX_VECTOR_DIMENSION)))
  }

  const batchSize = parsePositiveInt(process.env.INDEXER_EMBEDDING_BATCH_SIZE, 32)
  const output: number[][] = []

  for (let start = 0; start < inputs.length; start += batchSize) {
    const batch = inputs.slice(start, start + batchSize)
    const vectors = await requestOpenAiEmbeddings(batch)
    output.push(...vectors)
  }

  return output
}

const loadCache = async (chunkIds: string[]) => {
  if (chunkIds.length === 0) {
    return new Map<string, { model: string; embedding: number[] }>()
  }

  const rows = await db
    .select({
      chunkId: indexEmbeddingCache.chunkId,
      model: indexEmbeddingCache.model,
      embedding: indexEmbeddingCache.embedding,
    })
    .from(indexEmbeddingCache)
    .where(inArray(indexEmbeddingCache.chunkId, chunkIds))

  return new Map(rows.map((row) => [row.chunkId, { model: row.model, embedding: row.embedding }]))
}

const upsertCache = async (items: Array<{ chunkId: string; embedding: number[] }>): Promise<void> => {
  if (items.length === 0) {
    return
  }

  const now = new Date()
  const model = resolveCacheModelKey()

  await db
    .insert(indexEmbeddingCache)
    .values(
      items.map((item) => ({
        chunkId: item.chunkId,
        model,
        embedding: item.embedding,
        createdAt: now,
        updatedAt: now,
      })),
    )
    .onConflictDoUpdate({
      target: indexEmbeddingCache.chunkId,
      set: {
        model,
        embedding: sql`excluded.embedding`,
        updatedAt: now,
      },
    })
}

export const embedQueryText = async (query: string): Promise<number[]> => {
  const [embedding] = await embedTexts([query])
  if (!embedding) {
    throw new Error('Failed to embed query text.')
  }

  return embedding
}

export const embedVectorChunks = async (
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>,
): Promise<VectorChunkRecord[]> => {

  if (chunks.length === 0) {
    return []
  }

  const chunkIds = chunks.map((chunk) => chunk.chunkId)
  const model = resolveCacheModelKey()
  const cached = await loadCache(chunkIds)

  const misses: Array<{ chunkId: string; content: string }> = []
  for (const chunk of chunks) {
    const hit = cached.get(chunk.chunkId)
    if (!hit || hit.model !== model || hit.embedding.length !== INDEX_VECTOR_DIMENSION) {
      misses.push({ chunkId: chunk.chunkId, content: chunk.content })
    }
  }

  const missEmbeddings = new Map<string, number[]>()
  if (misses.length > 0) {
    const vectors = await embedTexts(misses.map((miss) => miss.content))
    misses.forEach((miss, index) => {
      const vector = vectors[index]
      if (!vector) {
        throw new Error(`Missing embedding response for chunk ${miss.chunkId}.`)
      }

      missEmbeddings.set(miss.chunkId, vector)
    })

    await upsertCache(
      misses.map((miss) => {
        const embedding = missEmbeddings.get(miss.chunkId)
        if (!embedding) {
          throw new Error(`Missing embedding cache payload for chunk ${miss.chunkId}.`)
        }

        return {
          chunkId: miss.chunkId,
          embedding,
        }
      }),
    )
  }

  return chunks.map((chunk) => {
    const cacheHit = cached.get(chunk.chunkId)
    const embedding = missEmbeddings.get(chunk.chunkId) ?? cacheHit?.embedding
    if (!embedding) {
      throw new Error(`Embedding unavailable for chunk ${chunk.chunkId}.`)
    }

    return {
      ...chunk,
      embedding: normalizeEmbedding(embedding),
    }
  })
}

