import { and, eq, inArray, isNull, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexFileStates,
  indexRunFileChanges,
  indexRuns,
} from '@/lib/db/schema'

type FinalizeStatus = 'ready' | 'superseded' | 'not_found' | 'invalid_state'

export type FinalizeIndexRunResult = {
  runId: string
  status: FinalizeStatus
}

const FINALIZABLE_STATUSES = new Set(['ingesting', 'indexing'])

export const markIndexRunFailed = async (
  runId: string,
  error: Record<string, unknown>,
): Promise<void> => {
  await db
    .update(indexRuns)
    .set({
      status: 'failed',
      error,
      updatedAt: new Date(),
    })
    .where(eq(indexRuns.id, runId))
}

export const finalizeIndexRun = async (runId: string): Promise<FinalizeIndexRunResult> => {
  return db.transaction(async (tx) => {
    const [run] = await tx
      .select({
        id: indexRuns.id,
        branchStateId: indexRuns.branchStateId,
        baseSha: indexRuns.baseSha,
        headSha: indexRuns.headSha,
        status: indexRuns.status,
      })
      .from(indexRuns)
      .where(eq(indexRuns.id, runId))
      .limit(1)

    if (!run) {
      return { runId, status: 'not_found' }
    }

    if (!FINALIZABLE_STATUSES.has(run.status)) {
      return { runId, status: 'invalid_state' }
    }

    const now = new Date()

    if (deletePaths.length > 0) {
      await tx
        .delete(indexFileStates)
        .where(
          and(
            eq(indexFileStates.branchStateId, run.branchStateId),
            inArray(indexFileStates.path, deletePaths),
          ),
        )
    }

    const upserts = stagedChanges.filter(
      (change) => change.changeType === 'upsert' && change.fileId && change.sizeBytes !== null,
    )

    if (upserts.length > 0) {
      await tx
        .insert(indexFileStates)
        .values(
          upserts.map((change) => ({
            branchStateId: run.branchStateId,
            path: change.path,
            fileId: change.fileId as string,
            sizeBytes: change.sizeBytes as number,
            skipReason: change.skipReason,
            lastReadySha: run.headSha,
            createdAt: now,
            updatedAt: now,
          })),
        )
        .onConflictDoUpdate({
          target: [indexFileStates.branchStateId, indexFileStates.path],
          set: {
            fileId: sql`excluded.file_id`,
            sizeBytes: sql`excluded.size_bytes`,
            skipReason: sql`excluded.skip_reason`,
            lastReadySha: run.headSha,
            updatedAt: now,
          },
        })
    }

    await tx
      .update(indexRuns)
      .set({
        status: 'ready',
        error: null,
        updatedAt: now,
      })
      .where(eq(indexRuns.id, run.id))

    return { runId: run.id, status: 'ready' }
  })
}

import path from 'node:path'

const SKIP_DIRS = new Set(['.git', 'node_modules', 'vendor', 'dist', 'build'])

const BINARY_EXTENSIONS = new Set([
  '.png',
  '.jpg',
  '.jpeg',
  '.gif',
  '.webp',
  '.ico',
  '.pdf',
  '.zip',
  '.gz',
  '.tar',
  '.tgz',
  '.7z',
  '.exe',
  '.dll',
  '.so',
  '.dylib',
  '.woff',
  '.woff2',
  '.ttf',
  '.otf',
  '.mp3',
  '.mp4',
  '.mov',
  '.avi',
])

export const DEFAULT_MAX_FILE_SIZE_BYTES = 512 * 1024

export const shouldSkipPath = (relativePath: string): boolean => {
  const normalized = relativePath.replace(/\\/g, '/').toLowerCase()
  const segments = normalized.split('/').filter(Boolean)
  return segments.some((segment) => SKIP_DIRS.has(segment))
}

export const isLikelyBinary = (relativePath: string, content: Buffer): boolean => {
  const ext = path.extname(relativePath).toLowerCase()
  if (BINARY_EXTENSIONS.has(ext)) {
    return true
  }

  const checkLength = Math.min(content.length, 8_192)
  for (let i = 0; i < checkLength; i += 1) {
    if (content[i] === 0) {
      return true
    }
  }

  return false
}

export const classifySkipReason = (args: {
  relativePath: string
  content: Buffer
  maxFileSizeBytes: number
}): 'path_excluded' | 'binary' | 'file_too_large' | null => {
  if (shouldSkipPath(args.relativePath)) {
    return 'path_excluded'
  }

  if (args.content.length > args.maxFileSizeBytes) {
    return 'file_too_large'
  }

  if (isLikelyBinary(args.relativePath, args.content)) {
    return 'binary'
  }

  return null
}

