import { and, eq } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexConfigs,
  indexRuns,
} from '@/lib/db/schema'
import type { GitLabSource, PlanJob } from '@/lib/indexing/contracts'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import type { PlannedRun } from '@/lib/indexing/types'

const DEFAULT_CONFIG_HASH = 'default-v1'

type PlanProcessorDeps = {
  source: GitLabSource
}

const defaultDeps = (): PlanProcessorDeps => ({
  source: createGitLabSource(),
})

const artifactsPrefixForRun = (args: {
  integrationId: string
  configHash: string
  branch: string
  headSha: string
  runId: string
}) =>
  [
    'integrations',
    args.integrationId,
    'runs',
    args.configHash,
    args.branch,
    args.headSha,
    args.runId,
  ].join('/')

export const planIndexRun = async (
  job: PlanJob,
  deps: PlanProcessorDeps = defaultDeps(),
): Promise<PlannedRun> => {
  const now = new Date()
  const configHash = job.configHash?.trim() || DEFAULT_CONFIG_HASH
  const configJson = job.configJson ?? {}
  const headSha = await deps.source.resolveHeadSha({
    integrationId: job.integrationId,
    branch: job.branch,
    hintedHeadSha: job.hintedHeadSha,
  })

await db
  .insert(indexConfigs)
  .values({
    integrationId: job.integrationId,
    configHash,
    configJson,
    active: true,
    createdAt: now,
    updatedAt: now,
  })
  .onConflictDoUpdate({
    target: [indexConfigs.integrationId, indexConfigs.configHash],
    set: {
      active: true,
      updatedAt: now,
    },
  })

const [branchState] = await db
  .insert(indexBranchStates)
  .values({
    integrationId: job.integrationId,
    branch: job.branch,
    configHash,
    createdAt: now,
    updatedAt: now,
  })
  .onConflictDoUpdate({
    target: [
      indexBranchStates.integrationId,
      indexBranchStates.branch,
      indexBranchStates.configHash,
    ],
    set: {
      updatedAt: now,
    },
  })
  .returning({
    id: indexBranchStates.id,
    lastReadySha: indexBranchStates.lastReadySha,
  })

const mode = branchState.lastReadySha ? 'delta' : 'snapshot'

const [inserted] = await db
  .insert(indexRuns)
  .values({
    branchStateId: branchState.id,
    headSha,
    baseSha: branchState.lastReadySha,
    mode,
    status: 'planned',
    artifactsPrefix: 'pending',
    createdAt: now,
    updatedAt: now,
  })
  .onConflictDoNothing()
  .returning({
    id: indexRuns.id,
    branchStateId: indexRuns.branchStateId,
    headSha: indexRuns.headSha,
    baseSha: indexRuns.baseSha,
    mode: indexRuns.mode,
  })

  const run =
    inserted ??
    (await db
      .select({
        id: indexRuns.id,
        branchStateId: indexRuns.branchStateId,
        headSha: indexRuns.headSha,
        baseSha: indexRuns.baseSha,
        mode: indexRuns.mode,
      })
      .from(indexRuns)
      .where(
        and(eq(indexRuns.branchStateId, branchState.id), eq(indexRuns.headSha, headSha)),
      )
      .limit(1)
      .then((rows) => rows[0]))

  if (!run) {
    throw new Error('Failed to create or fetch index run.')
  }

  const artifactsPrefix = artifactsPrefixForRun({
    integrationId: job.integrationId,
    configHash,
    branch: job.branch,
    headSha: run.headSha,
    runId: run.id,
  })

  await db
    .update(indexRuns)
    .set({
      artifactsPrefix,
      updatedAt: new Date(),
    })
    .where(eq(indexRuns.id, run.id))

  return {
    runId: run.id,
    branchStateId: run.branchStateId,
    headSha: run.headSha,
    baseSha: run.baseSha,
    mode: run.mode,
    created: Boolean(inserted),
  }
}

  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
}) {
  const isMobile = useIsMobile()
  const [openMobile, setOpenMobile] = React.useState(false)

  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen)
  const open = openProp ?? _open
  const openRef = React.useRef(open)
  React.useEffect(() => {
    openRef.current = open
  }, [open])

  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState =
        typeof value === "function" ? value(openRef.current) : value
      if (setOpenProp) {
        setOpenProp(openState)
      } else {
        _setOpen(openState)
      }
    },
    [setOpenProp]
  )

  React.useEffect(() => {
    // Keep persisted sidebar state in sync with the effective open value.
    document.cookie = `${SIDEBAR_COOKIE_NAME}=${open}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`
  }, [open])

  // Helper to toggle the sidebar.
  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open)
  }, [isMobile, setOpen, setOpenMobile])

  // Adds a keyboard shortcut to toggle the sidebar.

  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey)
      ) {
        event.preventDefault()
        toggleSidebar()
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [toggleSidebar])

  // We add a state so that we can do data-state="expanded" or "collapsed".
  // This makes it easier to style the sidebar with Tailwind classes.
  const state = open ? "expanded" : "collapsed"

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar]
  )

  return (
    <SidebarContext.Provider value={contextValue}>
      <TooltipProvider delayDuration={0}>
        <div
          data-slot="sidebar-wrapper"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH,
              "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
              ...style,
            } as React.CSSProperties
          }
          className={cn(
            "group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full",
            className
          )}
          {...props}
        >
          {children}
        </div>
      </TooltipProvider>
    </SidebarContext.Provider>
  )
}

function Sidebar({

  side = "left",
  variant = "sidebar",
  collapsible = "offcanvas",
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  side?: "left" | "right"
  variant?: "sidebar" | "floating" | "inset"
  collapsible?: "offcanvas" | "icon" | "none"
}) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar()

  if (collapsible === "none") {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
          className
        )}
        {...props}
      >
        {children}
      </div>
    )
  }

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
        <SheetContent
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          className="bg-sidebar text-sidebar-foreground w-(--sidebar-width) p-0 [&>button]:hidden"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
