export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const [userId, { integrationId }] = await Promise.all([
    getSessionUserId(),
    context.params,
  ])

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  const [integration, payload] = await Promise.all([
    getUserIntegration(integrationId, userId),
    request.json().catch(() => ({})),
  ])

  if (!integration) {
    return NextResponse.json({ error: "Integration not found." }, { status: 404 })
  }

  if (integration.status === "disabled") {
    return NextResponse.json({ error: "Integration is disabled." }, { status: 409 })
  }

  const parsed = enableSchema.safeParse(payload)
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid enable payload." }, { status: 400 })
  }

  try {
    const queuedJob = await enqueuePlanJob({
      integrationId: integration.id,
      branch: parsed.data.branch,
      hintedHeadSha: parsed.data.hintedHeadSha,
      configHash: parsed.data.configHash,
      configJson: parsed.data.configJson,
    })
    const reconcileJob = await enqueueReconcileJob({
      integrationId: integration.id,
    })

    return NextResponse.json({
      data: {
        integrationId: integration.id,
        branch: parsed.data.branch,
        job: queuedJob,
        reconcileJob,
      },
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : "Failed to enable indexing."
    return NextResponse.json({ error: message }, { status: 400 })
  }
}

