const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "error" in value) {
    return String((value as { error?: string }).error)
  }
  return "Unable to load merge request diff."
}

const getReviewErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "error" in value) {
    return String((value as { error?: string }).error)
  }
  return "Unable to complete AI review."
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const getEnvAiDefaults = (): AiSettings => ({
  apiUrl:
    process.env.NEXT_PUBLIC_AI_API_URL?.trim() ||
    process.env.NEXT_PUBLIC_OPENAI_BASE_URL?.trim() ||
    DEFAULT_AI_API_URL,
  model:
    process.env.NEXT_PUBLIC_AI_MODEL?.trim() ||
    process.env.NEXT_PUBLIC_OPENAI_MODEL?.trim() ||
    DEFAULT_AI_MODEL,
})

const parseAiSettings = (): AiSettings | null => {
  const envDefaults = getEnvAiDefaults()

  if (typeof window === "undefined") {
    return envDefaults
  }

  const raw = window.localStorage.getItem(AI_SETTINGS_STORAGE_KEY)
  if (!raw) {
    return envDefaults
  }

  try {
    const parsed = JSON.parse(raw) as Partial<AiSettings>
    const merged = {
      apiUrl:
        isNonEmptyString(parsed.apiUrl) ? parsed.apiUrl.trim() : envDefaults.apiUrl,
      model:
        isNonEmptyString(parsed.model) ? parsed.model.trim() : envDefaults.model,
    } satisfies AiSettings

    if (
      !isNonEmptyString(merged.apiUrl) ||
      !isNonEmptyString(merged.model)
    ) {
      return null
    }

    return merged
  } catch {
    return envDefaults
  }
}

const normalizePatchPath = (value: string) =>
  value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const toReviewSide = (value: unknown): ReviewFinding["side"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (
    normalized === "deletions" ||
    normalized === "deletion" ||
    normalized === "removed" ||
    normalized === "left"
  ) {
    return "deletions"
  }
  return "additions"
}

const toReviewSeverity = (value: unknown): ReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toReviewConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }
  return Math.max(0, Math.min(1, value))
}

const normalizeReviewFindings = (value: unknown): ReviewFinding[] => {
  if (!Array.isArray(value)) {
    return []
  }

  return value
    .map((item) => {
      if (!item || typeof item !== "object") {
        return null
      }

      const finding = item as Record<string, unknown>
      const file = String(finding.file ?? "").trim()
      const line = Number(finding.line)
      const title = String(finding.title ?? "").trim()
      const body = String(finding.body ?? finding.explanation ?? "").trim()

      if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
        return null
      }

      return {
        file,
        line: Math.floor(line),
        side: toReviewSide(finding.side),
        severity: toReviewSeverity(finding.severity),
        title,
        body,
        confidence: toReviewConfidence(finding.confidence),
      } satisfies ReviewFinding
    })
    .filter((item): item is ReviewFinding => item !== null)
}

const getFileLabel = (file: FileDiffMetadata) => {
  if (file.prevName && file.prevName !== file.name) {
    return `${file.prevName} -> ${file.name}`
  }

  return file.name
}

const getStableFileKey = (file: Pick<FileDiffMetadata, "cacheKey" | "prevName" | "name">) => {
  return file.cacheKey ?? `${file.prevName ?? ""}->${file.name}`
}

const splitPatchIntoFileChunks = (patchText: string) => {
  const splitByFile = patchText.split(/^diff --git /m)
  if (splitByFile.length <= 1) {
    return []
  }

  const metadataPrefix = splitByFile[0].trim()

  return splitByFile
    .slice(1)
    .map((part, index) => {
      const chunk = `diff --git ${part}`.trim()
      if (!chunk) {
        return ""
      }
      if (index === 0 && metadataPrefix) {
        return `${metadataPrefix}\n${chunk}`
      }
      return chunk
    })
    .filter((chunk): chunk is string => chunk.length > 0)
}

