let parsePatchFilesModulePromise: Promise<typeof import("@pierre/diffs")> | null = null
const getParsePatchFilesModule = async () => {
  parsePatchFilesModulePromise ??= import("@pierre/diffs")
  return await parsePatchFilesModulePromise
}

export function MergeRequestDiffViewer({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: MergeRequestDiffViewerProps) {
  const [isLoading, setIsLoading] = useState(false)
  const [loadError, setLoadError] = useState("")
  const [patchText, setPatchText] = useState("")
  const [dataSource, setDataSource] = useState<DiffDataSource | null>(null)

const [diffThemeMode, setDiffThemeMode] = useState<DiffThemeMode>("system")
const [collapsedFileKeys, setCollapsedFileKeys] = useState<Set<string>>(new Set())

const [filenameFilter, setFilenameFilter] = useState("")
const [diffStyle, setDiffStyle] = useState<DiffStyle>("split")
const [wrapLines, setWrapLines] = useState(false)
const [showLineNumbers, setShowLineNumbers] = useState(true)
const [visibleFileCount, setVisibleFileCount] = useState(INITIAL_FILE_BATCH_SIZE)
const [parsedFiles, setParsedFiles] = useState<FileDiffMetadata[]>([])
const [parseError, setParseError] = useState("")
const [loadProfile, setLoadProfile] = useState<DiffLoadProfile>({
  fetchMs: null,
  firstParseMs: null,
  fullParseMs: null,
})
const [isParsingInitialPatch, setIsParsingInitialPatch] = useState(false)
const [isParsingRemainingPatch, setIsParsingRemainingPatch] = useState(false)
const [isReviewing, setIsReviewing] = useState(false)
const [reviewError, setReviewError] = useState("")
const [reviewSummary, setReviewSummary] = useState("")
const [reviewFindings, setReviewFindings] = useState<ReviewFinding[]>([])
const { resolvedTheme } = useTheme()
const parseWorkerRef = useRef<Worker | null>(null)
const parseRequestIdRef = useRef(0)
const pendingParseRequestsRef = useRef<Map<number, PendingParseRequest>>(new Map())

const effectiveDiffThemeType: "system" | "light" | "dark" = useMemo(() => {
  if (diffThemeMode !== "system") {
    return diffThemeMode
  }

  if (resolvedTheme === "dark" || resolvedTheme === "argus-dark") {
    return "dark"
  }
  if (resolvedTheme === "light" || resolvedTheme === "argus-light") {
    return "light"
  }

  return "system"
}, [diffThemeMode, resolvedTheme])

useEffect(() => {
  let worker: Worker | null = null
  try {
    worker = new Worker(
      new URL("../workers/diff-parser.worker.ts", import.meta.url),
    )
  } catch {
    worker = null
  }

  parseWorkerRef.current = worker

  if (!worker) {
    return () => {
      parseWorkerRef.current = null
    }
  }

  const pendingParseRequests = pendingParseRequestsRef.current

  const handleMessage = (event: MessageEvent<ParsePatchWorkerResponse>) => {
    const { id, files, parseError: workerParseError } = event.data
    const pending = pendingParseRequests.get(id)
    if (!pending) {
      return
    }
    pendingParseRequests.delete(id)
    pending.resolve({
      files,
      parseError: workerParseError,
    })
  }

  const handleError = () => {
    const pendingRequests = Array.from(pendingParseRequests.values())
    pendingParseRequests.clear()
    for (const pending of pendingRequests) {
      pending.reject(new Error("Unable to parse merge request diff."))
    }
  }

  worker.addEventListener("message", handleMessage)
  worker.addEventListener("error", handleError)

  return () => {
    parseRequestIdRef.current += 1
    const pendingRequests = Array.from(pendingParseRequests.values())
    pendingParseRequests.clear()
    for (const pending of pendingRequests) {
      pending.reject(new Error("Unable to parse merge request diff."))
    }
    worker.removeEventListener("message", handleMessage)
    worker.removeEventListener("error", handleError)
    worker.terminate()
    if (parseWorkerRef.current === worker) {
      parseWorkerRef.current = null
    }
  }
}, [])

useEffect(() => {
  void getParsePatchFilesModule()
}, [])

const loadDiff = useCallback(async () => {

  const loadStart = getNow()
  setIsLoading(true)
  setLoadError("")

  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "merge-request-diff",
        instanceUrl,
        token,
        projectId,
        mergeRequestIid,
      }),
    })

    const payload = (await response.json().catch(() => null)) as DiffPayload | null
    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }

    if (!payload?.data || typeof payload.data.patch !== "string") {
      throw new Error("Unexpected diff response from server.")
    }

    const source = payload.data.source === "changes" ? "changes" : "raw_diffs"
    setPatchText(payload.data.patch)
    setDataSource(source)
    setCollapsedFileKeys(new Set())
    setLoadProfile({
      fetchMs: Math.round(getNow() - loadStart),
      firstParseMs: null,
      fullParseMs: null,
    })
    setVisibleFileCount(INITIAL_FILE_BATCH_SIZE)
    setReviewError("")
    setReviewSummary("")
    setReviewFindings([])
  } catch (error) {
    setPatchText("")
    setDataSource(null)
    setLoadError(getErrorMessage(error))
    setLoadProfile({
      fetchMs: null,
      firstParseMs: null,
      fullParseMs: null,
    })
    setReviewError("")
    setReviewSummary("")
    setReviewFindings([])
  } finally {
    setIsLoading(false)
  }
}, [instanceUrl, token, projectId, mergeRequestIid])

useEffect(() => {
  void loadDiff()
}, [loadDiff])

useEffect(() => {
  if (!patchText) {
    parseRequestIdRef.current += 1
    setParsedFiles([])
    setParseError("")
    setIsParsingInitialPatch(false)
    setIsParsingRemainingPatch(false)
    return
  }

  let cancelled = false

  const parsePatchText = async (
    nextPatchText: string,
    cacheKeyPrefix: string,
    preferMainThread = false,
  ): Promise<ParsePatchResult> => {

  if (preferMainThread) {
    const { parsePatchFiles } = await getParsePatchFilesModule()
    try {
      const patches = parsePatchFiles(nextPatchText, cacheKeyPrefix)
      return {
        files: patches.flatMap((patch) => patch.files),
        parseError: "",
      }
    } catch (error) {
      return {
        files: [],
        parseError: getErrorMessage(error),
      }
    }
  }

  const worker = parseWorkerRef.current
  if (worker) {
    const requestId = parseRequestIdRef.current + 1
    parseRequestIdRef.current = requestId

    return await new Promise<ParsePatchResult>((resolve, reject) => {
      pendingParseRequestsRef.current.set(requestId, { resolve, reject })
      try {
        worker.postMessage({
          id: requestId,
          patchText: nextPatchText,
          cacheKeyPrefix,
        })
      } catch (error) {
        pendingParseRequestsRef.current.delete(requestId)
        reject(error)
      }
    })
  }

  const { parsePatchFiles } = await getParsePatchFilesModule()
  try {
    const patches = parsePatchFiles(nextPatchText, cacheKeyPrefix)
    return {
      files: patches.flatMap((patch) => patch.files),
      parseError: "",
    }
  } catch (error) {
    return {
      files: [],
      parseError: getErrorMessage(error),
    }
  }
}

const parseIncrementally = async () => {
  const parseStart = getNow()

const cacheKeyPrefix = `mr-${projectId}-${mergeRequestIid}`
const patchChunks = splitPatchIntoFileChunks(patchText)
setParseError("")
setParsedFiles([])
setIsParsingInitialPatch(true)
setIsParsingRemainingPatch(false)

if (patchChunks.length === 0) {
  const result = await parsePatchText(patchText, cacheKeyPrefix)
  if (cancelled) {
    return
  }
  setParsedFiles(result.files)
  setParseError(result.parseError)
  setLoadProfile((current) => ({
    ...current,
    firstParseMs: Math.round(getNow() - parseStart),
    fullParseMs: Math.round(getNow() - parseStart),
  }))
  setIsParsingInitialPatch(false)
  return
}

const initialPatchChunk = patchChunks
  .slice(0, INITIAL_PARSE_FILE_BATCH_SIZE)
  .join("\n\n")
const initialResult = await parsePatchText(
  initialPatchChunk,
  `${cacheKeyPrefix}-batch-0`,
  true,
)
if (cancelled) {
  return
}

if (initialResult.files.length === 0 && initialResult.parseError) {
  setParsedFiles([])
  setParseError(initialResult.parseError)
  setIsParsingInitialPatch(false)
  return
}

let nextFiles = initialResult.files
let nextParseError = initialResult.parseError
setParsedFiles(nextFiles)
setCollapsedFileKeys(
  new Set(
    nextFiles
      .slice(1)
      .map((file) => getStableFileKey(file)),
  ),
)
setParseError(nextParseError)

setLoadProfile((current) => ({
  ...current,
  firstParseMs: Math.round(getNow() - parseStart),
}))
setIsParsingInitialPatch(false)

const hasRemainingChunks = patchChunks.length > INITIAL_PARSE_FILE_BATCH_SIZE
if (!hasRemainingChunks) {
  setLoadProfile((current) => ({
    ...current,
    fullParseMs: Math.round(getNow() - parseStart),
  }))
  return
}

setIsParsingRemainingPatch(true)

for (
  let start = INITIAL_PARSE_FILE_BATCH_SIZE;
  start < patchChunks.length;
  start += BACKGROUND_PARSE_FILE_BATCH_SIZE
) {
  const nextChunk = patchChunks
    .slice(start, start + BACKGROUND_PARSE_FILE_BATCH_SIZE)
    .join("\n\n")
  const batchResult = await parsePatchText(
    nextChunk,
    `${cacheKeyPrefix}-batch-${start}`,
  )

  if (cancelled) {
    return
  }

  if (batchResult.files.length > 0) {
    nextFiles = [...nextFiles, ...batchResult.files]
    setParsedFiles(nextFiles)
    setCollapsedFileKeys((current) => {
      const next = new Set(current)
      for (const file of batchResult.files) {
        next.add(getStableFileKey(file))
      }
      return next
    })
  }
  if (!nextParseError && batchResult.parseError) {
    nextParseError = batchResult.parseError
    setParseError(nextParseError)
  }
}

    if (!cancelled) {
      setLoadProfile((current) => ({
        ...current,
        fullParseMs: Math.round(getNow() - parseStart),
      }))
      setIsParsingRemainingPatch(false)
    }
  }

  void parseIncrementally().catch((error: unknown) => {
    if (cancelled) {
      return
    }
    setParsedFiles([])
    setParseError(getErrorMessage(error))
    setIsParsingInitialPatch(false)
    setIsParsingRemainingPatch(false)
  })

  return () => {
    cancelled = true
  }
}, [mergeRequestIid, patchText, projectId])

const normalizedFilter = filenameFilter.trim().toLowerCase()
const filteredFiles = useMemo(() => {
  if (!normalizedFilter) {
    return parsedFiles
  }

  return parsedFiles.filter((file) => {
    const label = getFileLabel(file).toLowerCase()
    return label.includes(normalizedFilter)
  })
}, [normalizedFilter, parsedFiles])

useEffect(() => {
  setVisibleFileCount(INITIAL_FILE_BATCH_SIZE)
}, [normalizedFilter, patchText])

const totals = useMemo(
  () =>
    filteredFiles.reduce(
      (accumulator, file) => {
        for (const hunk of file.hunks) {
          accumulator.additions += hunk.additionLines
          accumulator.deletions += hunk.deletionLines
        }
        return accumulator
      },
      { additions: 0, deletions: 0 },
    ),
  [filteredFiles],
)

const visibleFiles = filteredFiles.slice(0, visibleFileCount)
const canLoadMore = visibleFileCount < filteredFiles.length
const isDiffBusy = isLoading || isParsingInitialPatch

const isDiffLoading = isLoading || isParsingInitialPatch || isParsingRemainingPatch
const loadProfileSummary = useMemo(() => {
  if (!dataSource || loadProfile.fetchMs == null) {
    return ""
  }

  const parts = [`Source: ${dataSource === "changes" ? "changes" : "raw_diffs"}`, `fetch ${loadProfile.fetchMs}ms`]
  if (loadProfile.firstParseMs != null) {
    parts.push(`first parse ${loadProfile.firstParseMs}ms`)
  }
  if (loadProfile.fullParseMs != null) {
    parts.push(`full parse ${loadProfile.fullParseMs}ms`)
  }
  return parts.join(" · ")
}, [dataSource, loadProfile.fetchMs, loadProfile.firstParseMs, loadProfile.fullParseMs])

const getFileKey = useCallback((file: FileDiffMetadata) => {
  return getStableFileKey(file)
}, [])

const parsedFileLookup = useMemo(() => {
  const lookup = new Map<string, FileDiffMetadata>()
  for (const file of parsedFiles) {
    const candidates = [file.name, file.prevName].filter(
      (candidate): candidate is string => typeof candidate === "string" && candidate.length > 0,
    )

    for (const candidate of candidates) {
      const normalized = normalizePatchPath(candidate)
      if (!lookup.has(normalized)) {
        lookup.set(normalized, file)
      }
    }
  }
  return lookup
}, [parsedFiles])

const reviewAnnotationsByFileKey = useMemo<
  Record<string, DiffLineAnnotation<ReviewAnnotationMetadata>[]>
>(() => {
  const next: Record<string, DiffLineAnnotation<ReviewAnnotationMetadata>[]> = {}

  for (const finding of reviewFindings) {
    const targetFile = parsedFileLookup.get(normalizePatchPath(finding.file))
    if (!targetFile) {
      continue
    }

    const key = getFileKey(targetFile)
    const annotations = next[key] ?? []
    annotations.push({
      side: finding.side,
      lineNumber: finding.line,
      metadata: {
        severity: finding.severity,
        title: finding.title,
        body: finding.body,
        confidence: finding.confidence,
      },
    })
    next[key] = annotations
  }

  for (const annotations of Object.values(next)) {
    annotations.sort((a, b) => a.lineNumber - b.lineNumber)
  }

  return next
}, [getFileKey, parsedFileLookup, reviewFindings])

const clearReviewFindings = useCallback(() => {
  setReviewFindings([])
  setReviewError("")
  setReviewSummary("")
}, [])

const runAiReview = useCallback(async () => {
  if (!patchText.trim()) {
    setReviewError("Load a diff before running AI review.")
    setReviewSummary("")
    setReviewFindings([])
    return
  }

  const aiSettings = parseAiSettings()
  if (!aiSettings) {
    setReviewError("AI settings are missing. Set API URL and model in Settings.")
    setReviewSummary("")
    setReviewFindings([])
    return
  }

  setIsReviewing(true)
  setReviewError("")

  setReviewSummary("")

  try {
    const response = await fetch("/api/review/diff", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        patch: patchText,
        apiUrl: aiSettings.apiUrl,
        model: aiSettings.model,
      }),
    })

    const payload = (await response.json().catch(() => null)) as DiffReviewPayload | null
    if (!response.ok) {
      throw new Error(getReviewErrorMessage(payload))
    }

    const findings = normalizeReviewFindings(payload?.data?.findings)
    setReviewFindings(findings)

    if (findings.length === 0) {
      setReviewSummary("AI review complete. No findings.")
      return
    }

    const highCount = findings.filter((finding) => finding.severity === "high").length
    const medCount = findings.filter((finding) => finding.severity === "med").length
    const lowCount = findings.length - highCount - medCount
    setReviewSummary(
      `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`,
    )
  } catch (error) {
    setReviewFindings([])
    setReviewSummary("")
    setReviewError(getReviewErrorMessage(error))
  } finally {
    setIsReviewing(false)
  }
}, [patchText])

const renderReviewAnnotation = useCallback(
  (annotation: DiffLineAnnotation<ReviewAnnotationMetadata>) => {
    const metadata = annotation.metadata
    const accentClasses =
      metadata.severity === "high"
        ? "border-red-300/80 bg-red-50/90 dark:border-red-900/50 dark:bg-red-950/40"
        : metadata.severity === "med"
          ? "border-amber-300/80 bg-amber-50/90 dark:border-amber-900/40 dark:bg-amber-950/30"
          : "border-slate-300/80 bg-slate-50/80 dark:border-slate-700/70 dark:bg-slate-900/35"

    return (
      <div className={`mx-2 my-1 rounded border px-2 py-1.5 text-xs ${accentClasses}`}>
        <p className="font-medium leading-4">{metadata.title}</p>
        <p className="mt-1 whitespace-pre-wrap leading-4 text-muted-foreground">
          {metadata.body}
        </p>
        <p className="mt-1 text-[10px] uppercase tracking-wide text-muted-foreground">
          {metadata.severity}
          {` \u2022 ${Math.round(metadata.confidence * 100)}%`}
        </p>
      </div>
    )
  },
  [],
)

const toggleFileCollapsed = useCallback(
  (file: FileDiffMetadata) => {
    const key = getFileKey(file)
    setCollapsedFileKeys((current) => {
      const next = new Set(current)
      if (next.has(key)) {
        next.delete(key)
      } else {
        next.add(key)
      }
      return next
    })
  },
  [getFileKey],
)

const renderFileHeader = useCallback(
  (file: FileDiffMetadata) => {
    const key = getFileKey(file)

const [additions, deletions] = file.hunks.reduce(
  (counts, hunk) => {
    counts[0] += hunk.additionLines
    counts[1] += hunk.deletionLines
    return counts
  },
  [0, 0] as [number, number],
)

return (
  <div
    className="flex flex-wrap items-center gap-2 border-b px-2 py-2"
    style={{
      backgroundColor: headerBgColor,
      color:
        headerTextColor,
    }}
    onClick={() => toggleFileCollapsed(file)}
    onKeyDown={(event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault()
        toggleFileCollapsed(file)
      }
    }}
    role="button"
    tabIndex={0}
  >
    <Button
      type="button"
      size="icon-sm"
      variant="outline"
      onClick={(event) => {
        event.stopPropagation()
        toggleFileCollapsed(file)
      }}
      title={isCollapsed ? "Expand diff" : "Collapse diff"}
    >
      <ChevronRight
        className={`size-4 shrink-0 transition-all duration-200 ${
          isCollapsed ? "rotate-0" : "rotate-90"
        }`}
        aria-hidden="true"
      />
      <span className="sr-only">
        {isCollapsed ? "Expand diff" : "Collapse diff"}
      </span>
    </Button>

const diffOptions = useMemo(
  () => ({
    diffStyle,
    disableFileHeader: true,
    overflow: (wrapLines ? "wrap" : "scroll") as "wrap" | "scroll",
    disableLineNumbers: !showLineNumbers,
    lineDiffType: "word" as const,
    diffIndicators: "bars" as const,
    hunkSeparators: "line-info" as const,
    expansionLineCount: 20,
    tokenizeMaxLineLength: 1500,
    theme: DIFF_THEME,
    themeType: effectiveDiffThemeType,
  }),
  [diffStyle, showLineNumbers, wrapLines, effectiveDiffThemeType],
)

const poolOptions = useMemo(
  () => ({
    workerFactory: () =>
      new Worker(
        new URL("@pierre/diffs/worker/worker.js", import.meta.url),
      ),
    poolSize: workerPoolSize,
    totalASTLRUCacheSize: DIFF_CACHE_SIZE,
  }),
  [workerPoolSize],
)

const highlighterOptions = useMemo(
  () => ({
    theme: DIFF_THEME,
    lineDiffType: "word" as const,
    tokenizeMaxLineLength: 1500,
  }),
  [],
)

return (
  <Card className="border-border/60">
    <CardContent className="space-y-4 py-4">
      {/* Toolbar: stats, filter, controls */}
      <div className="flex flex-wrap items-center gap-3">
        {/* Stats */}

{!isDiffBusy && !loadError && !parseError && visibleFiles.length === 0 ? (
  <div className="rounded-md border border-dashed px-4 py-8 text-center text-sm text-muted-foreground">
    No files match your current filter.
  </div>
) : null}

{visibleFiles.length > 0 ? (
  <WorkerPoolContextProvider
    poolOptions={poolOptions}
    highlighterOptions={highlighterOptions}
  >
    <div className="space-y-4">
      {visibleFiles.map((file) => (
        <div
          key={getFileKey(file)}
          className="overflow-hidden rounded-lg border"
        >
          {renderFileHeader(file)}
          {!collapsedFileKeys.has(getFileKey(file)) ? (
            <FileDiff
              fileDiff={file}
              options={diffOptions}
              lineAnnotations={reviewAnnotationsByFileKey[getFileKey(file)]}
              renderAnnotation={renderReviewAnnotation}
              className="rounded-b-lg"
            />
          ) : null}
        </div>
      ))}
    </div>
  </WorkerPoolContextProvider>
) : null}

        {canLoadMore ? (
          <div className="pt-2">
            <Button
              type="button"
              variant="outline"
              onClick={() =>
                setVisibleFileCount((count) =>
                  Math.min(count + FILE_BATCH_SIZE, filteredFiles.length),
                )
              }
            >
              Load more files ({filteredFiles.length - visibleFileCount} remaining)
            </Button>
          </div>
        ) : null}
      </CardContent>
    </Card>
  )
}

