"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type CollapsibleContextValue = {
  open: boolean
  setOpen: (open: boolean) => void
}

const CollapsibleContext = React.createContext<CollapsibleContextValue | null>(null)

const useCollapsibleContext = () => {
  const context = React.useContext(CollapsibleContext)
  if (!context) {
    throw new Error("Collapsible components must be used within a Collapsible.")
  }
  return context
}

type CollapsibleProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  asChild?: boolean
  className?: string
  children: React.ReactNode
}

export const Collapsible = ({
  open,
  defaultOpen = false,
  onOpenChange,
  disabled = false,
  className,
  children,
}: CollapsibleProps) => {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const controlled = typeof open === "boolean"
  const isOpen = controlled ? open : internalOpen

  React.useEffect(() => {
    if (!controlled) {
      return
    }
    setInternalOpen(open)
  }, [controlled, open])

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (disabled) {
        return
      }

      if (!controlled) {
        setInternalOpen(nextOpen)
      }
      onOpenChange?.(nextOpen)
    },
    [disabled, controlled, onOpenChange],
  )

  return (
    <CollapsibleContext.Provider value={{ open: isOpen, setOpen }}>
      <div
        className={cn(
          "group/collapsible",
          "data-[state=open]:animate-in data-[state=closed]:animate-out",
          className,
        )}
        data-state={isOpen ? "open" : "closed"}
      >
        {children}
      </div>
    </CollapsibleContext.Provider>
  )
}

type CollapsibleTriggerProps = React.HTMLAttributes<HTMLElement> & {
  asChild?: boolean
}

export const CollapsibleTrigger = ({
  className,
  children,
  asChild,
  onClick,
  ...props
}: CollapsibleTriggerProps) => {
  const { open, setOpen } = useCollapsibleContext()

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    onClick?.(event)
    if (event.defaultPrevented) {
      return
    }
    setOpen(!open)
  }

  if (!asChild || !React.isValidElement(children)) {
    return (
      <button
        type="button"
        aria-expanded={open}
        onClick={handleClick}
        className={className}
        {...props}
      >
        {children}
      </button>
    )
  }

  const child = React.Children.only(children) as React.ReactElement<
    React.HTMLAttributes<HTMLElement> & { "data-state"?: string }
  >
  const childProps = child.props

  return React.cloneElement(child, {
    ...props,
    ...childProps,
    onClick: (event: React.MouseEvent<HTMLElement>) => {
      childProps.onClick?.(event)
      if (event.defaultPrevented) {
        return
      }
      handleClick(event)
    },
    "aria-expanded": childProps["aria-expanded"] ?? open,
    "data-state": open ? "open" : "closed",
    className: cn(childProps.className, className),
  })
}

type CollapsibleContentProps = React.HTMLAttributes<HTMLDivElement>

export const CollapsibleContent = ({ className, children, ...props }: CollapsibleContentProps) => {
  const { open } = useCollapsibleContext()

  return (
    <div
      className={cn(
        "data-[state=open]:animate-in data-[state=closed]:animate-out",
        "overflow-hidden",
        className,
      )}
      data-state={open ? "open" : "closed"}
      hidden={!open}
      {...props}
    >
      {children}
    </div>
  )
}

import { mkdtemp, writeFile } from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'

import { getIntegrationById, decryptIntegrationToken } from '@/lib/gitlab/service'
import type { GitLabCompareChange, GitLabSource } from '@/lib/indexing/contracts'

type IntegrationContext = {
  instanceUrl: string
  projectId: string
  token: string
}

type GitLabCompareResponse = {
  compare_timeout?: boolean
  diffs?: Array<{
    old_path?: string
    new_path?: string
    new_file?: boolean
    renamed_file?: boolean
    deleted_file?: boolean
  }>
}

type GitLabBranchResponse = {
  commit?: {
    id?: string
  }
}

const readErrorText = async (response: Response) => {
  const text = await response.text().catch(() => '')
  return text.slice(0, 1000)
}

const encodeProjectId = (projectId: string) => encodeURIComponent(projectId)

const loadIntegrationContext = async (integrationId: string): Promise<IntegrationContext> => {
  const integration = await getIntegrationById(integrationId)
  if (!integration) {
    throw new Error(`Integration ${integrationId} not found.`)
  }

  return {
    instanceUrl: integration.instanceUrl,
    projectId: integration.projectId,
    token: decryptIntegrationToken(integration),
  }
}

const gitLabRequest = async (args: {
  integration: IntegrationContext
  apiPath: string
}): Promise<Response> => {
  const response = await fetch(`${args.integration.instanceUrl}${args.apiPath}`, {
    headers: {
      'private-token': args.integration.token,
      'user-agent': 'argus-app',
    },
  })

  if (!response.ok) {
    const body = await readErrorText(response)
    throw new Error(
      `GitLab request failed (${response.status})${body ? `: ${body}` : ''}`,
    )
  }

  return response
}

const toCompareChangeType = (diff: {
  new_file?: boolean
  renamed_file?: boolean
  deleted_file?: boolean
}): GitLabCompareChange['type'] => {
  if (diff.deleted_file) {
    return 'deleted'
  }

  if (diff.renamed_file) {
    return 'renamed'
  }

  if (diff.new_file) {
    return 'added'
  }

  return 'modified'
}

export class GitLabApiSource implements GitLabSource {

async resolveHeadSha(args: {
  integrationId: string
  branch: string
  hintedHeadSha?: string
}): Promise<string> {
  const hinted = args.hintedHeadSha?.trim()
  if (hinted) {
    return hinted
  }

  const integration = await loadIntegrationContext(args.integrationId)
  const encodedProjectId = encodeProjectId(integration.projectId)
  const encodedBranch = encodeURIComponent(args.branch)

  const response = await gitLabRequest({
    integration,
    apiPath: `/api/v4/projects/${encodedProjectId}/repository/branches/${encodedBranch}`,
  })

  const payload = (await response.json()) as GitLabBranchResponse
  const commitId = payload.commit?.id?.trim()
  if (!commitId) {
    throw new Error(`Unable to resolve head SHA for branch ${args.branch}.`)
  }

  return commitId
}

async compare(args: {
  integrationId: string
  fromSha: string
  toSha: string
}): Promise<{
  valid: boolean
  incomplete: boolean
  changes: GitLabCompareChange[]
}> {
  try {
    const integration = await loadIntegrationContext(args.integrationId)
    const encodedProjectId = encodeProjectId(integration.projectId)
    const from = encodeURIComponent(args.fromSha)
    const to = encodeURIComponent(args.toSha)

    const response = await gitLabRequest({
      integration,
      apiPath: `/api/v4/projects/${encodedProjectId}/repository/compare?from=${from}&to=${to}`,
    })

    const payload = (await response.json()) as GitLabCompareResponse
    const diffs = payload.diffs ?? []
    const changes: GitLabCompareChange[] = diffs.map((diff) => ({
      oldPath: diff.old_path ?? null,
      newPath: diff.new_path ?? null,
      type: toCompareChangeType(diff),
    }))

    return {
      valid: true,
      incomplete: Boolean(payload.compare_timeout),
      changes,
    }
  } catch {
    return {
      valid: false,
      incomplete: true,
      changes: [],
    }
  }
}

  async fetchFile(args: {
    integrationId: string
    path: string
    ref: string
  }): Promise<{
    path: string
    content: Buffer
  }> {
    const integration = await loadIntegrationContext(args.integrationId)
    const encodedProjectId = encodeProjectId(integration.projectId)
    const filePath = encodeURIComponent(args.path)
    const ref = encodeURIComponent(args.ref)

    const response = await gitLabRequest({
      integration,
      apiPath: `/api/v4/projects/${encodedProjectId}/repository/files/${filePath}/raw?ref=${ref}`,
    })

    const content = Buffer.from(await response.arrayBuffer())
    return {
      path: args.path,
      content,
    }
  }

  async downloadArchive(args: {
    integrationId: string
    sha: string
  }): Promise<{
    archivePath: string
  }> {
    const integration = await loadIntegrationContext(args.integrationId)
    const encodedProjectId = encodeProjectId(integration.projectId)
    const sha = encodeURIComponent(args.sha)

    const response = await gitLabRequest({
      integration,
      apiPath: `/api/v4/projects/${encodedProjectId}/repository/archive.tar.gz?sha=${sha}`,
    })

    const archiveBytes = Buffer.from(await response.arrayBuffer())
    const tempDir = await mkdtemp(path.join(os.tmpdir(), 'argus-indexer-archive-'))
    const archivePath = path.join(tempDir, 'source.tar.gz')
    await writeFile(archivePath, archiveBytes)

    return {
      archivePath,
    }
  }
}

export const createGitLabSource = () => new GitLabApiSource()

