const MERGE_REQUESTS_PRELOAD_CONCURRENCY = 3
const ONBOARDING_QUERY_STALE_TIME = 10 * 60_000
const ONBOARDING_QUERY_GC_TIME = 30 * 60_000
const ONBOARDING_PREFETCH_STALE_TIME = 15 * 60_000
const ONBOARDING_QUERY_KEY_PREFIX = ["onboarding"] as const

const routeStepPosition: Record<OnboardingRouteStep, number> = {
  tokens: 1,
  projects: 2,
  mrs: 3,
}

const getInstanceByKey = (instance: string) =>
  INSTANCE_PRESETS.find((item) => item.key === instance) ?? INSTANCE_PRESETS[0]

const isInstanceKey = (instance: string): instance is GitLabInstancePreset["key"] =>
  INSTANCE_PRESETS.some((item) => item.key === instance)

const resolveGitLabInstance = (instance: string, customValue: string) => {
  const selectedInstance = getInstanceByKey(instance)
  const value =
    (selectedInstance.isCustom ? customValue : selectedInstance.defaultUrl).trim()
  if (!value) {
    throw new Error("Please select or enter a GitLab instance.")
  }
  return value.replace(/\/+$/, "")
}

const buildEmptyInstanceTokens = () => {
  const values: Record<string, string> = {}
  for (const instance of INSTANCE_PRESETS) {
    values[instance.key] = ""
  }
  return values
}

const isStringRecord = (value: unknown): value is Record<string, string> =>
  Boolean(value) &&
  typeof value === "object" &&
  !Array.isArray(value) &&
  Object.values(value as Record<string, unknown>).every((item) => typeof item === "string")

const readPersistedState = (): Partial<OnboardingSessionState> => {
  const raw = window.sessionStorage.getItem(ONBOARDING_STORAGE_KEY)
  if (!raw) {
    return {}
  }

  try {
    const parsed = JSON.parse(raw) as Partial<OnboardingSessionState>
    return parsed && typeof parsed === "object" ? parsed : {}
  } catch {
    return {}
  }
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const hashTokenForCache = (value: string) => {
  let hash = 0x811c9dc5
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, "0")
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value instanceof Error) {
    return value.message
  }
  if (value && typeof value === "object" && "error" in value) {
    return String((value as { error?: string }).error)
  }
  return "Something went wrong."
}
type TokenTestResultCache = Map<
  string,
  { checkedAt: number; feedback: TokenTestFeedback }
>

const loadTokenTestCache = () => {
  const raw = window.sessionStorage.getItem(ONBOARDING_TOKEN_TEST_CACHE_KEY)
  if (!raw) {
    return new Map<string, { checkedAt: number; feedback: TokenTestFeedback }>()
  }

  try {
    const parsed = JSON.parse(raw) as Record<
      string,
      { checkedAt: number; feedback: TokenTestFeedback } | undefined
    >
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return new Map()
    }

    const entries = Object.entries(parsed).filter(([, item]) => {
      if (!item || typeof item !== "object") {
        return false
      }
      if (typeof item.checkedAt !== "number" || !Number.isFinite(item.checkedAt)) {
        return false
      }
      if (!item.feedback || typeof item.feedback !== "object") {
        return false
      }
      if (
        item.feedback.kind !== "success" &&
        item.feedback.kind !== "error"
      ) {
        return false
      }
      if (typeof item.feedback.message !== "string") {
        return false
      }
      return true
    })

    return new Map(entries)
  } catch {
    return new Map()
  }
}

const pruneTokenTestCache = (cache: TokenTestResultCache, now: number) => {
  for (const [signature, entry] of cache) {
    if (now - entry.checkedAt >= TOKEN_TEST_CACHE_TTL_MS) {
      cache.delete(signature)
    }
  }
}

const persistTokenTestCache = (cache: TokenTestResultCache) => {
  try {
    const now = Date.now()
    pruneTokenTestCache(cache, now)
    const payload = Object.fromEntries(cache.entries())
    window.sessionStorage.setItem(ONBOARDING_TOKEN_TEST_CACHE_KEY, JSON.stringify(payload))
  } catch {
    // best-effort
  }
}

export function OnboardingFlow({ routeStep }: { routeStep: OnboardingRouteStep }) {
  const router = useRouter()
  const currentStep = routeStepPosition[routeStep]
  const queryClient = useQueryClient()
  const startedEventTracked = useRef(false)
  const completionEventTracked = useRef(false)
  const persistedStateSnapshotRef = useRef("")
  const persistenceTimeoutRef = useRef<number | null>(null)
  const projectSelectionHandlerRef = useRef<
    ((projectId: string) => Promise<void>) | null
  >(null)
  const mergeRequestSelectionHandlerRef = useRef<((mrId: string) => void) | null>(null)
  const previousProjectsCacheKeyRef = useRef<string | null>(null)
  const integrationConnectInFlightRef = useRef(new Set<string>())
  const tokenTestSignatureRef = useRef<string | null>(null)
  const tokenTestRunRef = useRef(0)
  const tokenAutoTestTimeoutRef = useRef<number | null>(null)
  const tokenTestResultCacheRef = useRef<TokenTestResultCache>(new Map())

  const [isHydrated, setIsHydrated] = useState(false)

  const [gitlabInstance, setGitlabInstance] = useState(INSTANCE_PRESETS[0].key)
  const [customInstance, setCustomInstance] = useState("https://")
  const [instanceTokens, setInstanceTokens] = useState<Record<string, string>>(
    buildEmptyInstanceTokens,
  )

const [token, setToken] = useState("")
const [projects, setProjects] = useState<Project[]>([])
const [projectsError, setProjectsError] = useState("")
const [selectedProjectId, setSelectedProjectId] = useState("")
const [projectSearchQuery, setProjectSearchQuery] = useState("")

const [mergeRequests, setMergeRequests] = useState<MergeRequest[]>([])
const [mergeRequestsError, setMergeRequestsError] = useState("")
const [selectedMergeRequestId, setSelectedMergeRequestId] = useState("")
const [actionBusy, setActionBusy] = useState(false)
const [tokenTestBusy, setTokenTestBusy] = useState(false)
const [tokenTestFeedback, setTokenTestFeedback] =
  useState<TokenTestFeedback | null>(null)
const [webhookSetupFeedback, setWebhookSetupFeedback] =
  useState<WebhookSetupFeedback | null>(null)

const selectedProject = projects.find((project) => project.id === selectedProjectId)
const selectedMergeRequest = mergeRequests.find((mr) => mr.id === selectedMergeRequestId)

const canLoadProjects = useMemo(
  () =>
    token.trim().length > 0 &&
    (getInstanceByKey(gitlabInstance).isCustom
      ? customInstance.trim().length > 0
      : getInstanceByKey(gitlabInstance).defaultUrl.trim().length > 0),
  [token, gitlabInstance, customInstance],
)
const normalizedProjectSearchQuery = useMemo(
  () => projectSearchQuery.trim().toLowerCase(),
  [projectSearchQuery],
)

const filteredProjects = useMemo(() => {
  if (!normalizedProjectSearchQuery) {
    return projects
  }

  return projects.filter((project) => {
    const name = project.name.toLowerCase()
    const path = project.path.toLowerCase()
    return (
      name.includes(normalizedProjectSearchQuery) ||
      path.includes(normalizedProjectSearchQuery)
    )
  })
}, [projects, normalizedProjectSearchQuery])
const recentProjects = useMemo(
  () => filteredProjects.slice(0, RECENT_PROJECTS_LIMIT),
  [filteredProjects],
)
const resolvedGitLabInstance = useMemo(() => {
  if (!token.trim()) {
    return ""
  }

  try {
    return resolveGitLabInstance(gitlabInstance, customInstance)
  } catch {
    return ""
  }
}, [token, gitlabInstance, customInstance])
const tokenCacheHash = useMemo(() => {
  const trimmed = token.trim()
  if (!trimmed) {
    return ""
  }
  return hashTokenForCache(trimmed)
}, [token])
const projectsCacheKey = useMemo(() => {
  if (!tokenCacheHash) {
    return ""
  }

  try {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    return `${normalizedInstance}::${tokenCacheHash}`
  } catch {
    return ""
  }
}, [tokenCacheHash, gitlabInstance, customInstance])

const trackEvent = (
  event:
    | "onboarding_started"
    | "onboarding_token_validated"
    | "onboarding_projects_selected"
    | "onboarding_completed",
  metadata?: OnboardingEventMetadata,
) => {
  const body = JSON.stringify({ event, metadata })

  if (typeof navigator !== "undefined" && typeof navigator.sendBeacon === "function") {
    try {
      const sent = navigator.sendBeacon(
        "/api/onboarding/track",
        new Blob([body], { type: "application/json" }),
      )
      if (sent) {
        return
      }
    } catch {
    }
  }

  void fetch("/api/onboarding/track", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body,
    keepalive: true,
  }).catch(() => null)
}

const connectIntegration = useCallback(async (project: Project) => {
  const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
  const connectKey = `${normalizedInstance}::${project.id}`
  if (integrationConnectInFlightRef.current.has(connectKey)) {
    return
  }

  integrationConnectInFlightRef.current.add(connectKey)

  try {
    const response = await fetch("/api/gitlab/integrations/connect", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        instanceUrl: normalizedInstance,
        token,
        projectId: project.id,
        projectPath: project.path,
        projectName: project.name,
      }),
    })

    const payload = await response.json().catch(() => null)

    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }

    const warning =
      payload &&
      typeof payload === "object" &&
      "warning" in payload &&
      typeof (payload as { warning?: unknown }).warning === "string"
        ? (payload as { warning: string }).warning
        : ""

    if (warning) {
      setWebhookSetupFeedback({
        kind: "warning",
        message: warning,
      })
      return
    }

    setWebhookSetupFeedback({
      kind: "success",
      message: `Webhook active for ${project.path}.`,
    })
  } catch (error) {
    setWebhookSetupFeedback({
      kind: "warning",
      message: `Webhook setup warning: ${getErrorMessage(error)}`,
    })
  } finally {
    integrationConnectInFlightRef.current.delete(connectKey)
  }
}, [gitlabInstance, customInstance, token])

const callGitLab = useCallback(async (
  action: "projects" | "merge-requests",
  options?: { projectId?: string; perPage?: number },
) => {
  const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
  const response = await fetch("/api/gitlab", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      action,
      instanceUrl: normalizedInstance,
      token,
      ...(options?.projectId ? { projectId: options.projectId } : {}),
      ...(typeof options?.perPage === "number" ? { perPage: options.perPage } : {}),
    }),
  })

  const payload = await response.json()
  if (!response.ok) {
    throw new Error(getErrorMessage(payload))
  }

  if (!Array.isArray(payload.data)) {
    throw new Error("Unexpected response from server.")
  }

  return payload.data
}, [gitlabInstance, customInstance, token])

const projectsQueryKey = useCallback(
  () => ["onboarding", "projects", projectsCacheKey] as const,
  [projectsCacheKey],
)
const mergeRequestsQueryKey = useCallback(
  (projectId: string, perPage: number) =>
    ["onboarding", "merge-requests", projectsCacheKey, projectId, perPage] as const,
  [projectsCacheKey],
)

const applyLoadedProjects = useCallback((data: Project[]) => {
  setProjects(data)
  setSelectedProjectId("")
  setMergeRequests([])
  setSelectedMergeRequestId("")
}, [])

const fetchMergeRequests = useCallback(async (
  projectId: string,
  { perPage = MERGE_REQUESTS_FULL_LIMIT }: { perPage?: number } = {},
) => {
  const normalizedPerPage = Math.min(
    MERGE_REQUESTS_FULL_LIMIT,
    Math.max(1, Math.floor(perPage)),
  )
  if (!projectsCacheKey) {
    throw new Error("Personal access token is required.")
  }

  const queryKey = mergeRequestsQueryKey(projectId, normalizedPerPage)
  const cached = queryClient.getQueryData<MergeRequest[]>(queryKey)
  if (cached !== undefined) {
    return cached
  }

  return queryClient.fetchQuery({
    queryKey,
    queryFn: () =>
      callGitLab("merge-requests", {
        projectId,
        perPage: normalizedPerPage,
      }) as Promise<MergeRequest[]>,
    staleTime: ONBOARDING_QUERY_STALE_TIME,
    gcTime: ONBOARDING_QUERY_GC_TIME,
  })
}, [callGitLab, mergeRequestsQueryKey, projectsCacheKey, queryClient])

const fetchProjects = useCallback(async ({ force = false }: { force?: boolean } = {}) => {
  if (!projectsCacheKey) {
    throw new Error("Personal access token is required.")
  }

  if (force) {
    await queryClient.invalidateQueries({ queryKey: projectsQueryKey(), exact: true })
  }

  return queryClient.fetchQuery({
    queryKey: projectsQueryKey(),
    queryFn: () => callGitLab("projects") as Promise<Project[]>,
    staleTime: ONBOARDING_QUERY_STALE_TIME,
    gcTime: ONBOARDING_QUERY_GC_TIME,
  })
}, [callGitLab, projectsCacheKey, projectsQueryKey, queryClient])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  if (previousProjectsCacheKeyRef.current === null) {
    previousProjectsCacheKeyRef.current = projectsCacheKey
    return
  }

  if (previousProjectsCacheKeyRef.current === projectsCacheKey) {
    return
  }

  previousProjectsCacheKeyRef.current = projectsCacheKey
  void queryClient.removeQueries({ queryKey: ONBOARDING_QUERY_KEY_PREFIX })
}, [isHydrated, projectsCacheKey, queryClient])

const preloadProjectsForContinue = () => {
  if (!canLoadProjects || actionBusy || tokenTestBusy) {
    return
  }

  router.prefetch("/onboarding/projects")
  void fetchProjects().catch(() => null)
}

const loadProjects = async ({ force = false }: { force?: boolean } = {}) => {
  setActionBusy(true)
  setProjectsError("")
  setMergeRequestsError("")
  setTokenTestFeedback(null)

  try {
    const data = await fetchProjects({ force })
    applyLoadedProjects(data)
    void trackEvent("onboarding_token_validated", {
      instanceUrl: resolveGitLabInstance(gitlabInstance, customInstance),
    })
    return true
  } catch (error) {
    setProjectsError(getErrorMessage(error))
    return false
  } finally {
    setActionBusy(false)
  }
}

const testToken = useCallback(async (signature: string) => {
  const runId = ++tokenTestRunRef.current
  setTokenTestBusy(true)
  setProjectsError("")
  setMergeRequestsError("")
  setTokenTestFeedback(null)

  try {
    const data = await fetchProjects()
    if (tokenTestSignatureRef.current !== signature || runId !== tokenTestRunRef.current) {
      return
    }
    applyLoadedProjects(data)
    const countLabel = data.length === 1 ? "1 project" : `${data.length} projects`
    const feedback: TokenTestFeedback = {
      kind: "success",
      message: `Token is valid. Found ${countLabel}.`,
    }
    tokenTestResultCacheRef.current.set(signature, { checkedAt: Date.now(), feedback })
    persistTokenTestCache(tokenTestResultCacheRef.current)
    setTokenTestFeedback(feedback)
  } catch (error) {
    if (tokenTestSignatureRef.current !== signature || runId !== tokenTestRunRef.current) {
      return
    }
    const feedback: TokenTestFeedback = {
      kind: "error",
      message: getErrorMessage(error),
    }
    tokenTestResultCacheRef.current.set(signature, { checkedAt: Date.now(), feedback })
    persistTokenTestCache(tokenTestResultCacheRef.current)
    setTokenTestFeedback(feedback)
  } finally {
    if (runId === tokenTestRunRef.current) {
      setTokenTestBusy(false)
    }
  }
}, [applyLoadedProjects, fetchProjects])

useEffect(() => {

  if (!isHydrated || routeStep !== "tokens" || !canLoadProjects || actionBusy) {
    tokenTestRunRef.current += 1
    setTokenTestBusy(false)
    if (!canLoadProjects) {
      tokenTestSignatureRef.current = null
    }
    if (tokenAutoTestTimeoutRef.current !== null) {
      window.clearTimeout(tokenAutoTestTimeoutRef.current)
      tokenAutoTestTimeoutRef.current = null
    }
    return
  }

  const signature = `${resolvedGitLabInstance}::${tokenCacheHash}`
  const cached = tokenTestResultCacheRef.current.get(signature)
  const now = Date.now()

  if (cached && now - cached.checkedAt < TOKEN_TEST_CACHE_TTL_MS) {
    setTokenTestFeedback(cached.feedback)
    tokenTestSignatureRef.current = signature
    return
  }
  if (cached) {
    tokenTestResultCacheRef.current.delete(signature)
    persistTokenTestCache(tokenTestResultCacheRef.current)
    if (tokenTestSignatureRef.current === signature) {
      tokenTestSignatureRef.current = null
    }
  }

  if (tokenTestSignatureRef.current === signature) {
    return
  }

  if (tokenAutoTestTimeoutRef.current !== null) {
    window.clearTimeout(tokenAutoTestTimeoutRef.current)
  }

  tokenAutoTestTimeoutRef.current = window.setTimeout(() => {
    tokenTestSignatureRef.current = signature
    void testToken(signature)
  }, AUTOTEST_TOKEN_DEBOUNCE_MS)

  return () => {
    if (tokenAutoTestTimeoutRef.current !== null) {
      window.clearTimeout(tokenAutoTestTimeoutRef.current)
      tokenAutoTestTimeoutRef.current = null
    }
  }
}, [

  actionBusy,
  canLoadProjects,
  isHydrated,
  resolvedGitLabInstance,
  routeStep,
  tokenCacheHash,
  testToken,
])

const loadMergeRequests = async (
  projectId: string,
  options?: {
    skipNavigation?: boolean
    skipTracking?: boolean
    preserveSelection?: boolean
    setBusy?: boolean
  },
) => {
  const shouldSetBusy = options?.setBusy ?? true
  if (shouldSetBusy) {
    setActionBusy(true)
  }
  setMergeRequestsError("")

  try {
    const data = await fetchMergeRequests(projectId, {
      perPage: MERGE_REQUESTS_FULL_LIMIT,
    })
    setMergeRequests(data)
    setSelectedMergeRequestId((current) => {
      if (options?.preserveSelection && data.some((mr) => mr.id === current)) {
        return current
      }
      return ""
    })
    if (!options?.skipTracking) {
      void trackEvent("onboarding_projects_selected", {
        selectedProjectCount: projects.length,
        projectId,
      })
    }
    if (!options?.skipNavigation) {
      router.push("/onboarding/mrs")
    }
  } catch (error) {
    setMergeRequestsError(getErrorMessage(error))
  } finally {
    if (shouldSetBusy) {
      setActionBusy(false)
    }
  }
}

const handleTokenSubmit = async (event: FormEvent<HTMLFormElement>) => {
  event.preventDefault()
  const success = await loadProjects()
  if (success) {
    router.push("/onboarding/projects")
  }
}

const handleInstanceChange = (instanceKey: string) => {
  if (!isInstanceKey(instanceKey)) {
    return
  }

  setGitlabInstance(instanceKey)
  setToken(instanceTokens[instanceKey] ?? "")
  setTokenTestFeedback(null)
  setWebhookSetupFeedback(null)
}

const handleTokenChange = (nextToken: string) => {
  setToken(nextToken)
  setInstanceTokens((current) => ({
    ...current,
    [gitlabInstance]: nextToken,
  }))
}

const handleProjectSelection = async (projectId: string) => {
  const selectedProjectData = projects.find((project) => project.id === projectId)
  if (selectedProjectData) {
    void connectIntegration(selectedProjectData)
  }

  setSelectedProjectId(projectId)
  setSelectedMergeRequestId("")
  setMergeRequestsError("")

  const fullCacheKey = mergeRequestsQueryKey(projectId, MERGE_REQUESTS_FULL_LIMIT)
  const preloadedCacheKey = mergeRequestsQueryKey(projectId, MERGE_REQUESTS_PRELOAD_LIMIT)
  const cachedFullMergeRequests = queryClient.getQueryData<MergeRequest[]>(fullCacheKey)
  const cachedPreloadedMergeRequests = queryClient.getQueryData<MergeRequest[]>(preloadedCacheKey)

  if (cachedFullMergeRequests !== undefined) {
    setMergeRequests(cachedFullMergeRequests)
    router.push("/onboarding/mrs")
    void trackEvent("onboarding_projects_selected", {
      selectedProjectCount: projects.length,
      projectId,
    })
    return
  }

  if (cachedPreloadedMergeRequests !== undefined) {
    setMergeRequests(cachedPreloadedMergeRequests)
    router.push("/onboarding/mrs")
    void trackEvent("onboarding_projects_selected", {
      selectedProjectCount: projects.length,
      projectId,
    })

    if (cachedPreloadedMergeRequests.length >= MERGE_REQUESTS_PRELOAD_LIMIT) {
      void loadMergeRequests(projectId, {
        skipNavigation: true,
        skipTracking: true,
        preserveSelection: true,
        setBusy: false,
      })
    }
    return
  }

  await loadMergeRequests(projectId)
}

projectSelectionHandlerRef.current = handleProjectSelection

const handleMergeRequestSelection = (mrId: string) => {
  setSelectedMergeRequestId(mrId)
  if (!completionEventTracked.current) {
    completionEventTracked.current = true
    void trackEvent("onboarding_completed", {
      projectId: selectedProjectId,
      mergeRequestId: mrId,
    })
  }
}
mergeRequestSelectionHandlerRef.current = handleMergeRequestSelection

useEffect(() => {
  const persistedSnapshot = window.sessionStorage.getItem(ONBOARDING_STORAGE_KEY)
  if (persistedSnapshot) {
    persistedStateSnapshotRef.current = persistedSnapshot
  }

  const persisted = readPersistedState()
  const persistedGitlabInstance = persisted.gitlabInstance && isInstanceKey(persisted.gitlabInstance)
    ? persisted.gitlabInstance
    : INSTANCE_PRESETS[0].key
  const nextInstanceTokens = {
    ...buildEmptyInstanceTokens(),
    ...((persisted.instanceTokens && isStringRecord(persisted.instanceTokens))
      ? persisted.instanceTokens
      : {}),
  }

  setGitlabInstance(persistedGitlabInstance)
  if (isNonEmptyString(persisted.customInstance)) {
    setCustomInstance(persisted.customInstance)
  }
  if (isNonEmptyString(persisted.token) && persisted.gitlabInstance && isInstanceKey(persisted.gitlabInstance)) {
    nextInstanceTokens[persisted.gitlabInstance] = persisted.token
  }

  setInstanceTokens(nextInstanceTokens)
  setToken(nextInstanceTokens[persistedGitlabInstance] ?? "")

  if (Array.isArray(persisted.projects)) {
    const persistedProjects = persisted.projects as Project[]
    setProjects(persistedProjects)
  }
  if (isNonEmptyString(persisted.selectedProjectId)) {
    setSelectedProjectId(persisted.selectedProjectId)
  }
  if (Array.isArray(persisted.mergeRequests)) {
    setMergeRequests(persisted.mergeRequests as MergeRequest[])
  }
  if (isNonEmptyString(persisted.selectedMergeRequestId)) {
    setSelectedMergeRequestId(persisted.selectedMergeRequestId)
  }
  if (
    persisted.webhookSetupFeedback &&
    typeof persisted.webhookSetupFeedback === "object" &&
    (persisted.webhookSetupFeedback.kind === "success" ||
      persisted.webhookSetupFeedback.kind === "warning") &&
    typeof persisted.webhookSetupFeedback.message === "string"
  ) {
    setWebhookSetupFeedback({
      kind: persisted.webhookSetupFeedback.kind,
      message: persisted.webhookSetupFeedback.message,
    })
  }

  const loadedTokenTestCache = loadTokenTestCache()
  pruneTokenTestCache(loadedTokenTestCache, Date.now())
  tokenTestResultCacheRef.current = loadedTokenTestCache
  persistTokenTestCache(loadedTokenTestCache)
  setIsHydrated(true)
}, [])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  const persistedState = {
    gitlabInstance,
    customInstance,
    instanceTokens,
    token,
    projects: projects.slice(0, RECENT_PROJECTS_LIMIT),
    selectedProjectId,
    mergeRequests: mergeRequests.slice(0, MERGE_REQUESTS_PRELOAD_LIMIT),
    selectedMergeRequestId,
    webhookSetupFeedback,
  } satisfies OnboardingSessionState
  const serializedState = JSON.stringify(persistedState)

  if (serializedState === persistedStateSnapshotRef.current) {
    return
  }

  if (persistenceTimeoutRef.current !== null) {
    window.clearTimeout(persistenceTimeoutRef.current)
  }

  persistenceTimeoutRef.current = window.setTimeout(() => {
    window.sessionStorage.setItem(ONBOARDING_STORAGE_KEY, serializedState)
    persistedStateSnapshotRef.current = serializedState
    persistenceTimeoutRef.current = null
  }, 200)

  return () => {
    if (persistenceTimeoutRef.current !== null) {
      window.clearTimeout(persistenceTimeoutRef.current)
      persistenceTimeoutRef.current = null
    }
  }
}, [
  isHydrated,
  gitlabInstance,
  customInstance,
  instanceTokens,
  token,
  projects,
  selectedProjectId,
  mergeRequests,
  selectedMergeRequestId,
  webhookSetupFeedback,
])

useEffect(() => {
  if (!isHydrated) {
    return
  }
  if (routeStep !== "tokens") {
    return
  }
  if (startedEventTracked.current) {
    return
  }

  startedEventTracked.current = true
  void trackEvent("onboarding_started")
}, [isHydrated, routeStep])

useEffect(() => {
  setTokenTestFeedback(null)
  setWebhookSetupFeedback(null)
}, [token, gitlabInstance, customInstance])

useEffect(() => {
  if (!isHydrated) {
    return
  }

  if (routeStep === "projects" && !token.trim()) {
    router.replace("/onboarding/tokens")
    return
  }

  if (routeStep === "mrs" && !selectedProjectId) {
    router.replace("/onboarding/projects")
  }
}, [isHydrated, routeStep, token, selectedProjectId, router])

useEffect(() => {
  if (!isHydrated || routeStep !== "projects" || !projectsCacheKey || projects.length === 0) {
    return
  }

  const projectIds = projects
    .slice(0, MERGE_REQUESTS_PRELOAD_PROJECTS_LIMIT)
    .map((project) => project.id)
  let cancelled = false

  const preloadMergeRequests = async () => {
    const workerCount = Math.min(MERGE_REQUESTS_PRELOAD_CONCURRENCY, projectIds.length)
    let nextProjectIndex = 0

    const workers = Array.from({ length: workerCount }, () => async () => {
      while (!cancelled) {
        const projectId = projectIds[nextProjectIndex]
        nextProjectIndex += 1

        if (!projectId) {
          return
        }

        await queryClient
          .prefetchQuery({
            queryKey: mergeRequestsQueryKey(projectId, MERGE_REQUESTS_PRELOAD_LIMIT),
            queryFn: () =>
              callGitLab("merge-requests", {
                projectId,
                perPage: MERGE_REQUESTS_PRELOAD_LIMIT,
              }) as Promise<MergeRequest[]>,
            staleTime: ONBOARDING_PREFETCH_STALE_TIME,
            gcTime: ONBOARDING_QUERY_GC_TIME,
          })
          .catch(() => null)
      }
    })

    await Promise.allSettled(workers.map((worker) => worker()))
  }

  void preloadMergeRequests()

  return () => {
    cancelled = true
  }
}, [
  callGitLab,
  isHydrated,
  mergeRequestsQueryKey,
  projects,
  projectsCacheKey,
  queryClient,
  routeStep,
])

useEffect(() => {
  if (
    !isHydrated ||
    actionBusy ||
    (routeStep !== "projects" && routeStep !== "mrs") ||
    (routeStep === "projects" && recentProjects.length === 0) ||
    (routeStep === "mrs" && mergeRequests.length === 0)
  ) {
    return
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (
      event.defaultPrevented ||
      event.metaKey ||
      event.ctrlKey ||
      event.altKey ||
      event.repeat
    ) {
      return
    }

    const target = event.target as HTMLElement | null
    if (
      target &&
      (target.tagName === "INPUT" ||
        target.tagName === "TEXTAREA" ||
        target.tagName === "SELECT" ||
        target.isContentEditable)
    ) {
      return
    }

    if (!/^[0-9]$/.test(event.key)) {
      return
    }

    const index = event.key === "0" ? RECENT_PROJECTS_LIMIT - 1 : Number(event.key) - 1
    if (routeStep === "projects") {
      const project = recentProjects[index]
      if (!project) {
        return
      }

      event.preventDefault()
      void projectSelectionHandlerRef.current?.(project.id)
      return
    }

    const mergeRequest = mergeRequests[index]
    if (!mergeRequest) {
      return
    }
    event.preventDefault()
    mergeRequestSelectionHandlerRef.current?.(mergeRequest.id)
  }

  window.addEventListener("keydown", onKeyDown)
  return () => window.removeEventListener("keydown", onKeyDown)
}, [isHydrated, routeStep, actionBusy, recentProjects, mergeRequests])

if (routeStep === "tokens") {
  return (
    <OnboardingTokenStep
      currentStep={currentStep}
      instances={INSTANCE_PRESETS}
      gitlabInstance={gitlabInstance}
      customInstance={customInstance}
      token={token}
      tokenTestFeedback={tokenTestFeedback}
      projectsError={projectsError}
      canLoadProjects={canLoadProjects}
      actionBusy={actionBusy}
      tokenTestBusy={tokenTestBusy}
      onGitlabInstanceChange={handleInstanceChange}
      onCustomInstanceChange={setCustomInstance}
      onTokenChange={handleTokenChange}
      onSubmit={handleTokenSubmit}
      onPrefetchContinue={preloadProjectsForContinue}
    />
  )
}

if (routeStep === "projects") {
  return (
    <OnboardingProjectsStep
      currentStep={currentStep}
      canLoadProjects={canLoadProjects}
      actionBusy={actionBusy}
      hasProjects={projects.length > 0}
      selectedProjectId={selectedProjectId}
      projectSearchQuery={projectSearchQuery}
      normalizedProjectSearchQuery={normalizedProjectSearchQuery}
      recentProjects={recentProjects}
      projectsError={projectsError}
      mergeRequestsError={mergeRequestsError}
      webhookSetupFeedback={webhookSetupFeedback}
      shortcutLimit={RECENT_PROJECTS_LIMIT}
      onSearchChange={setProjectSearchQuery}
      onBackToTokens={() => router.push("/onboarding/tokens")}
      onReloadProjects={() => void loadProjects({ force: true })}
      onProjectSelect={(projectId) => void handleProjectSelection(projectId)}
      onPrefetchContinue={preloadProjectsForContinue}
    />
  )
}

  return (
    <OnboardingMergeRequestsStep
      currentStep={currentStep}
      selectedProject={selectedProject}
      selectedMergeRequest={selectedMergeRequest}
      selectedMergeRequestId={selectedMergeRequestId}
      mergeRequests={mergeRequests}
      resolvedGitLabInstance={resolvedGitLabInstance}
      token={token}
      actionBusy={actionBusy}
      mergeRequestsError={mergeRequestsError}
      webhookSetupFeedback={webhookSetupFeedback}
      shortcutLimit={RECENT_PROJECTS_LIMIT}
      onBackToProjects={() => router.push("/onboarding/projects")}
      onReloadMergeRequests={() =>
        void (
          selectedProjectId &&
          loadMergeRequests(selectedProjectId, {
            skipNavigation: true,
            skipTracking: true,
            preserveSelection: true,
          })
        )
      }
      onSelectMergeRequest={handleMergeRequestSelection}
    />
  )
}

