import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration, resyncGitLabIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"

const resyncSchema = z.object({
  token: z.string().optional(),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const [userId, { integrationId }] = await Promise.all([
    getSessionUserId(),
    context.params,
  ])

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  const [integration, payload] = await Promise.all([
    getUserIntegration(integrationId, userId),
    request.json().catch(() => ({})),
  ])

  if (!integration) {
    return NextResponse.json({ error: "Integration not found." }, { status: 404 })
  }

  const parsed = resyncSchema.safeParse(payload)
  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid resync payload." }, { status: 400 })
  }

  try {
    const result = await resyncGitLabIntegration({
      integration,
      token: parsed.data.token,
    })

    return NextResponse.json({ data: result.integration, warning: result.warning })
  } catch (error) {
    const message = error instanceof Error ? error.message : "Failed to resync integration."
    return NextResponse.json({ error: message }, { status: 400 })
  }
}

