import {
  createCipheriv,
  createDecipheriv,
  createHash,
  randomBytes,
  timingSafeEqual,
} from "node:crypto"
import { gitlabEnv } from "@/lib/gitlab/env"

type EncryptedToken = {
  ciphertext: string
  iv: string
  authTag: string
}

const toBase64 = (value: Buffer) => value.toString("base64")

const fromBase64 = (value: string, fieldName: string) => {
  try {
    return Buffer.from(value, "base64")
  } catch {
    throw new Error(`Invalid ${fieldName} encoding.`)
  }
}

export const generateWebhookSecret = () => randomBytes(32).toString("base64url")

export const hashWebhookSecret = (secret: string) =>
  createHash("sha256").update(secret).digest("hex")

export const secureCompare = (left: string, right: string) => {
  const leftBuffer = Buffer.from(left)
  const rightBuffer = Buffer.from(right)
  if (leftBuffer.length !== rightBuffer.length) {
    return false
  }
  return timingSafeEqual(leftBuffer, rightBuffer)
}

export const verifyWebhookSecretHash = (providedSecret: string, storedSecretHash: string) => {
  const providedHash = hashWebhookSecret(providedSecret)
  return secureCompare(providedHash, storedSecretHash)
}

export const encryptGitLabToken = (
  token: string,
  key: Buffer = gitlabEnv.tokenEncryptionKey,
): EncryptedToken => {
  const iv = randomBytes(12)
  const cipher = createCipheriv("aes-256-gcm", key, iv)
  const ciphertext = Buffer.concat([cipher.update(token, "utf8"), cipher.final()])
  const authTag = cipher.getAuthTag()

  return {
    ciphertext: toBase64(ciphertext),
    iv: toBase64(iv),
    authTag: toBase64(authTag),
  }
}

export const decryptGitLabToken = (
  encrypted: EncryptedToken,
  key: Buffer = gitlabEnv.tokenEncryptionKey,
) => {
  const iv = fromBase64(encrypted.iv, "token_iv")
  const ciphertext = fromBase64(encrypted.ciphertext, "token_ciphertext")
  const authTag = fromBase64(encrypted.authTag, "token_auth_tag")

  try {
    const decipher = createDecipheriv("aes-256-gcm", key, iv)
    decipher.setAuthTag(authTag)
    const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()])
    return plaintext.toString("utf8")
  } catch {
    throw new Error("Unable to decrypt GitLab token.")
  }
}

import { NextResponse } from "next/server"

import { verifyWebhookSecretHash } from "@/lib/gitlab/crypto"
import { getIntegrationById, ingestWebhookDelivery } from "@/lib/gitlab/service"
import { classifyWebhookEvent } from "@/lib/gitlab/webhook"

const readPayload = async (request: Request): Promise<Record<string, unknown> | null> => {
  const parsed = await request.json().catch(() => null)
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return null
  }

  return parsed as Record<string, unknown>
}

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  const integration = await getIntegrationById(integrationId)

  if (!integration || integration.status === "disabled") {
    return NextResponse.json({ error: "Integration not found." }, { status: 404 })
  }

  const providedSecret = request.headers.get("x-gitlab-token")
  if (!providedSecret || !integration.webhookSecretHash) {
    return NextResponse.json({ error: "Unauthorized webhook." }, { status: 401 })
  }

  if (!verifyWebhookSecretHash(providedSecret, integration.webhookSecretHash)) {
    return NextResponse.json({ error: "Unauthorized webhook." }, { status: 401 })
  }

  const eventUuid = request.headers.get("x-gitlab-event-uuid")
  if (!eventUuid || !eventUuid.trim()) {
    return NextResponse.json({ error: "Missing X-Gitlab-Event-UUID header." }, { status: 400 })
  }

  const eventName = request.headers.get("x-gitlab-event")

  if (!eventName || !eventName.trim()) {
    return NextResponse.json({ error: "Missing X-Gitlab-Event header." }, { status: 400 })
  }

  const payload = await readPayload(request)
  if (!payload) {
    return NextResponse.json({ error: "Invalid webhook payload." }, { status: 400 })
  }

  const classified = classifyWebhookEvent(eventName, payload)
  const ingestResult = await ingestWebhookDelivery({
    integrationId: integration.id,
    eventUuid: eventUuid.trim(),
    eventName: eventName.trim(),
    eventType: classified.eventType,
    ref: classified.ref,
    payload,
    jobType: classified.jobType,
    normalizedPayload: classified.normalizedPayload,
  })

  return NextResponse.json(
    {
      ok: true,
      deduped: ingestResult.deduped,
      enqueued: ingestResult.enqueued,
    },
    { status: 202 },
  )
}

